local function getHidden()
    if type(gethui) == "function" then
        local ok, v = pcall(gethui)
        if ok and v then return v end
    end
    if type(get_hidden_gui) == "function" then
        local ok, v = pcall(get_hidden_gui)
        if ok and v then return v end
    end
    return game:GetService("CoreGui")
end

local HOST = getHidden()
local PARENT = HOST:FindFirstChild("RobloxGui") or HOST

local function norm(s)
    s = tostring(s or "")
    s = string.lower(s)
    s = s:gsub("[^%w%+%-%%%./ ]+", "")
    s = s:gsub("%s+", " ")
    s = s:match("^%s*(.-)%s*$")
    return s
end

-- TEMPLATE and META are embedded below

-- ---------------------------------------------------------------------------
-- lifecycle: a new instance makes every old instance delete itself
-- (destroys old GUIs, kills old loops via a shared generation token, clears draw)
-- ---------------------------------------------------------------------------
if type(_G.KomaruCleanup) == "function" then pcall(_G.KomaruCleanup) end
local MYRUN = { gen = (type(_G.KomaruGen) == "number" and _G.KomaruGen or 0) + 1 }
_G.KomaruGen = MYRUN.gen
_G.KomaruState = MYRUN
local function alive() return _G.KomaruState == MYRUN end

local KOMARU_GUIS = { "KomaruHub", "KomaruToast", "KomaruESP", "KomaruFOV", "KomaruLauncher", "KomaruDim", "KomaruFPS", "KomaruMobile", "KomaruCursor", "KomaruPlayerMenu" }
local function wipeKomaruGuis()
    for _, h in ipairs({ HOST, game:GetService("CoreGui"), LP:FindFirstChild("PlayerGui") }) do
        if h then
            for _, nm in ipairs(KOMARU_GUIS) do
                local o = h:FindFirstChild(nm)
                if o then pcall(function() o:Destroy() end) end
            end
        end
    end
    for _, nm in ipairs({ "KomaruWeather", "KomaruSkyExtras", "KomaruBeam", "KomaruSkyBeam" }) do
        local o = workspace:FindFirstChild(nm)
        if o then pcall(function() o:Destroy() end) end
    end
end
wipeKomaruGuis()

_G.KomaruCleanup = function()
    if _G.KomaruState == MYRUN then _G.KomaruState = nil end
    if _G.Komaru and _G.Komaru.S then
        for k, v in pairs(_G.Komaru.S) do
            if type(v) == "boolean" then pcall(function() _G.Komaru.S[k] = false end) end
        end
    end
    if type(_G.KomaruVisReset) == "function" then pcall(_G.KomaruVisReset) end
    wipeKomaruGuis()
    if type(cleardrawcache) == "function" then pcall(cleardrawcache) end
end

local created = {}
for i, e in ipairs(TEMPLATE) do
    local inst = Instance.new(e[1])
    inst.Name = e[2]
    local props = e[4]
    for p, v in pairs(props) do
        pcall(function() inst[p] = v end)
    end
    created[i] = inst
    local pidx = e[3]
    if pidx == 0 then
        inst.Parent = PARENT
    else
        inst.Parent = created[pidx]
    end
end

