GUI.Name = "KomaruHub"
GUI.Enabled = true
GUI.ResetOnSpawn = false
GUI.DisplayOrder = 2147483000

for _, d in ipairs(GUI:GetDescendants()) do
    if d:IsA("TextBox") then
        pcall(function() d.TextTransparency = 0 end)
    elseif (d:IsA("TextLabel") or d:IsA("TextButton")) and d.Text ~= "" and d.TextTransparency >= 0.99 then
        pcall(function() d.TextTransparency = 0 end)
    end
    if (d:IsA("ImageLabel") or d:IsA("ImageButton")) and d.Image ~= "" and string.find(d.Image, "pulse_logo", 1, true) then
        pcall(function() d.Image = "" d.Visible = false end)
    end
    if d:IsA("Frame") and d.Name == "Row" then
        local hit = d:FindFirstChild("Hit")
        if hit and hit:IsA("GuiObject") then pcall(function() hit.ZIndex = 60 end) end
    end
    if d:IsA("Frame") and d.Name == "Switch" then
        pcall(function()
            d.ClipsDescendants = true
            local knob = d:FindFirstChild("Knob")
            if knob then
                local uc = knob:FindFirstChildOfClass("UICorner")
                if not uc then uc = Instance.new("UICorner") uc.Parent = knob end
                uc.CornerRadius = UDim.new(1, 0)
                knob.BackgroundTransparency = 1
                for _, sd in ipairs(knob:GetDescendants()) do
                    if sd.ClassName == "UIShadow" then pcall(function() sd:Destroy() end) end
                end
            end
