-- ---- remove "* Method" dropdowns (we only implement a single method) -------
do
    local function rowLbl(row)
        for _, c in ipairs(row:GetChildren()) do
            if c:IsA("TextLabel") and c.Text ~= "" then return string.lower(c.Text) end
        end
        return ""
    end
    for _, d in ipairs(GUI:GetDescendants()) do
        if d:IsA("Frame") and d.Name == "Row" then
            if string.find(rowLbl(d), "method", 1, true) then
                d:SetAttribute("komaruHidden", true)
                pcall(function() d.Visible = false end)
            end
        end
    end
end

do
    local MAINBODY = GUI.Root.Window.Main.Body
    local autoSet = {}
    for _, r in ipairs(GUI:GetDescendants()) do
        if r:IsA("Frame") and r.Name == "Row" then
            local p = r.Parent
            while p and p ~= MAINBODY do
                if p.Parent ~= MAINBODY and p:IsA("GuiObject") and not p:IsA("ScrollingFrame") and p.AutomaticSize == Enum.AutomaticSize.None then
                    autoSet[p] = true
                end
                p = p.Parent
            end
        end
    end
    for f in pairs(autoSet) do
        pcall(function() f.AutomaticSize = Enum.AutomaticSize.Y end)
    end
    for _, d in ipairs(GUI:GetDescendants()) do
        if d:IsA("ScrollingFrame") and d.AutomaticCanvasSize == Enum.AutomaticSize.None then
            pcall(function() d.AutomaticCanvasSize = Enum.AutomaticSize.Y end)
        end
    end
end

local ROOT = GUI:FindFirstChild("Root")
if ROOT and ROOT:IsA("GuiObject") then
    ROOT.Visible = true
    local launcher = GUI:FindFirstChild("Launcher")
    if launcher then
        launcher.Visible = false
        local lb = launcher:IsA("GuiButton") and launcher or launcher:FindFirstChildWhichIsA("GuiButton", true)
        if lb then
            lb.MouseButton1Click:Connect(function()
                ROOT.Visible = not ROOT.Visible
            end)
        end
    end
    local function center()
        local ap, as = ROOT.AbsolutePosition, ROOT.AbsoluteSize
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
        local delta = Vector2.new(vp.X / 2 - (ap.X + as.X / 2), vp.Y / 2 - (ap.Y + as.Y / 2))
        ROOT.Position = UDim2.new(ROOT.Position.X.Scale, ROOT.Position.X.Offset + delta.X, ROOT.Position.Y.Scale, ROOT.Position.Y.Offset + delta.Y)
    end
    task.defer(center)
    task.delay(0.5, center)
end

