local function recomputeScrolls()
    for _, d in ipairs(GUI:GetDescendants()) do
        if d:IsA("ScrollingFrame") then
            local maxB = 0
            for _, c in ipairs(d:GetDescendants()) do
                if c:IsA("GuiObject") and c.Visible then
                    local b = (c.AbsolutePosition.Y - d.AbsolutePosition.Y) + c.AbsoluteSize.Y
                    if b > maxB then maxB = b end
                end
            end
            if maxB > 0 then
                pcall(function() d.CanvasSize = UDim2.new(0, 0, 0, math.ceil(maxB) + 8) end)
            end
        end
    end
end

