local S = {
    speedOn = false, speed = 16,
    jumpOn = false, jump = 50,
    gravityOn = false, gravity = 196.2,
    hipOn = false, hip = 0,
    fly = false, flySpeed = 60,
    noclip = false, infJump = false, bhop = false, antiAfk = false,
    esp = false, espNames = true, espBox = true, espTracer = false,
    fullbright = false, bright = 2,
    aimbot = false, silentAim = false, autoShoot = false, aimFov = 220, aimTarget = "Murderer",
    killAura = false, killRange = 12,
    antiFling = false,
    invis = false,
    autoFarm = false,
}

local ROLE_COLORS = {
    Murderer = Color3.fromRGB(255, 70, 70),
    Sheriff = Color3.fromRGB(90, 170, 255),
    Innocent = Color3.fromRGB(90, 220, 120),
}

local function getChar()
    local char = LP.Character
    return char, char and char:FindFirstChildOfClass("Humanoid")
end

local function getRole(player)
    local char = player.Character
    if not char then return "Innocent" end
    local tool = char:FindFirstChildOfClass("Tool")
    if not tool and player.Backpack then
        tool = player.Backpack:FindFirstChildOfClass("Tool")
    end
    if tool then
        local n = string.lower(tool.Name)
        if string.find(n, "knife", 1, true) then return "Murderer" end
        if string.find(n, "gun", 1, true) or string.find(n, "revolver", 1, true) then return "Sheriff" end
    end
    return "Innocent"
end

