-- continuous feature loops
--------------------------------------------------------------------------
local hipDefaults = setmetatable({}, { __mode = "k" })
local function defaultHip(hum)
    local d = hipDefaults[hum]
    if d == nil then
        d = hum.HipHeight
        if d == 0 and hum.RigType == Enum.HumanoidRigType.R15 then d = 1.8345 end
        hipDefaults[hum] = d
    end
    return d
end
local function wantHip(hum)
    return S.hipOn and S.hip or defaultHip(hum)
end

task.spawn(function()
    while task.wait(0.2) do
        if not alive() then return end
        local char, hum = getChar()
        if hum then
            local wantSpeed = S.speedOn and S.speed or 16
            if math.abs(hum.WalkSpeed - wantSpeed) > 0.05 then hum.WalkSpeed = wantSpeed end
            local wantJump = S.jumpOn and S.jump or 50
            if hum.UseJumpPower then
                if math.abs(hum.JumpPower - wantJump) > 0.05 then hum.JumpPower = wantJump end
            else
                local wantH = S.jumpOn and (S.jump / 7.5) or 7.2
                if math.abs(hum.JumpHeight - wantH) > 0.1 then hum.JumpHeight = wantH end
            end
            local wHip = wantHip(hum)
            if math.abs(hum.HipHeight - wHip) > 0.01 then hum.HipHeight = wHip end
        end
        local wantG = S.gravityOn and S.gravity or 196.2
        if math.abs(workspace.Gravity - wantG) > 0.05 then workspace.Gravity = wantG end
    end
end)

-- keep HipHeight correct every frame so stale script copies can't leave it at 0
RunService.RenderStepped:Connect(function()
    if not alive() then return end
    local _, hum = getChar()
    if hum then
        local wHip = wantHip(hum)
        if math.abs(hum.HipHeight - wHip) > 0.01 then hum.HipHeight = wHip end
    end
end)

local wasFlying = false
local function stopFly()
    wasFlying = false
    local _, hum = getChar()
    if hum then
        pcall(function() hum.PlatformStand = false end)
        pcall(function() hum.AutoRotate = true end)
    end
end

RunService.RenderStepped:Connect(function(dt)
    if not alive() then return end
    local char, hum = getChar()
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not S.fly then
        if wasFlying then stopFly() end
        return
    end
    if not (root and hum) then return end
    wasFlying = true
    hum.PlatformStand = true
    hum.AutoRotate = false
    local cam = workspace.CurrentCamera
    local dir = Vector3.zero
    if UIS:IsKeyDown(Enum.KeyCode.W) then dir += cam.CFrame.LookVector end
    if UIS:IsKeyDown(Enum.KeyCode.S) then dir -= cam.CFrame.LookVector end
    if UIS:IsKeyDown(Enum.KeyCode.A) then dir -= cam.CFrame.RightVector end
    if UIS:IsKeyDown(Enum.KeyCode.D) then dir += cam.CFrame.RightVector end
    if UIS:IsKeyDown(Enum.KeyCode.Space) then dir += Vector3.yAxis end
    if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then dir -= Vector3.yAxis end
    if dir.Magnitude > 0 then
        local np = root.Position + dir.Unit * S.flySpeed * dt
        root.CFrame = CFrame.new(np, np + cam.CFrame.LookVector)
    else
        root.CFrame = root.CFrame
    end
    root.AssemblyLinearVelocity = Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
end)

local noclipParts = {}
local noclipChar = nil
local function noclipRestore()
    for part, orig in pairs(noclipParts) do
        if part and part.Parent then part.CanCollide = orig end
    end
    noclipParts = {}
    noclipChar = nil
end

local function noclipApply(char)
    if not char or not char:FindFirstChildOfClass("Humanoid") then return end
    if noclipChar ~= char then
        noclipRestore()
        noclipChar = char
    end
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") then
            if noclipParts[part] == nil then noclipParts[part] = part.CanCollide end
            if part.CanCollide then part.CanCollide = false end
        end
    end
    for part in pairs(noclipParts) do
        if not part.Parent then noclipParts[part] = nil end
    end
end

task.spawn(function()
    while task.wait(0.12) do
        if not S.noclip then
            if next(noclipParts) then noclipRestore() end
        else
            noclipApply(LP.Character)
        end
    end
end)

LP.CharacterAdded:Connect(function(char)
    if S.noclip then
        task.wait(0.3)
        noclipApply(char)
    else
        noclipRestore()
    end
end)

