local origLight = {}
local function setFullbright(on)
    if on then
        if not origLight.done then
            origLight.done = true
            origLight.brightness = Lighting.Brightness
            origLight.ambient = Lighting.Ambient
            origLight.outdoor = Lighting.OutdoorAmbient
        end
        Lighting.Brightness = S.bright
        Lighting.Ambient = Color3.fromRGB(180, 180, 180)
        Lighting.OutdoorAmbient = Color3.fromRGB(180, 180, 180)
    elseif origLight.done then
        origLight.done = false
        Lighting.Brightness = origLight.brightness
        Lighting.Ambient = origLight.ambient
        Lighting.OutdoorAmbient = origLight.outdoor
    end
end

--------------------------------------------------------------------------
-- ESP
--------------------------------------------------------------------------
local espCache = {}
local function newDraw(kind)
    local ok, obj = pcall(function() return Drawing.new(kind) end)
    if ok then return obj end
    return nil
end
local function clearESP()
    for _, d in pairs(espCache) do
        if d.box then pcall(function() d.box:Remove() end) end
        if d.name then pcall(function() d.name:Remove() end) end
        if d.line then pcall(function() d.line:Remove() end) end
    end
    espCache = {}
end

RunService.RenderStepped:Connect(function()
    if not alive() then return end
    if S.espV2 ~= false then return end
    if not S.esp then
        if next(espCache) then clearESP() end
        return
    end
    local cam = workspace.CurrentCamera
    if not cam then return end
    local alive = {}
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LP and player.Character then
            local char = player.Character
            local root = char:FindFirstChild("HumanoidRootPart")
            local head = char:FindFirstChild("Head")
            local hum = char:FindFirstChildOfClass("Humanoid")
            if root and head and hum and hum.Health > 0 then
                alive[player] = true
                local top = head.Position + Vector3.new(0, 1.2, 0)
                local bottom = root.Position - Vector3.new(0, 3, 0)
                local topV, topOn = cam:WorldToViewportPoint(top)
                local botV, botOn = cam:WorldToViewportPoint(bottom)
                local entry = espCache[player]
                if not entry then
                    entry = { box = newDraw("Square"), name = newDraw("Text"), line = newDraw("Line") }
                    espCache[player] = entry
                end
                local role = getRole(player)
                local color = ROLE_COLORS[role] or ROLE_COLORS.Innocent
                local showRole = (role == "Murderer" and S.espShowMurderer ~= false)
                    or (role == "Sheriff" and S.espShowSheriff ~= false)
                    or (role == "Innocent" and S.espShowInnocent ~= false)
                if topOn and botOn and showRole then
                    local h = math.abs(botV.Y - topV.Y)
                    local w = h * 0.55
                    if entry.box then
                        entry.box.Visible = S.espBox
                        entry.box.Size = Vector2.new(w, h)
                        entry.box.Position = Vector2.new(topV.X - w / 2, topV.Y)
                        entry.box.Color = color
                        entry.box.Thickness = 1
                        entry.box.Transparency = 1
                    end
                    if entry.name then
                        entry.name.Visible = S.espNames
                        entry.name.Text = string.format("%s | %s | %dm", player.Name, role, math.floor((root.Position - cam.CFrame.Position).Magnitude))
                        entry.name.Size = 13
                        entry.name.Center = true
                        entry.name.Outline = true
                        entry.name.Color = color
                        entry.name.Position = Vector2.new(topV.X, topV.Y - 16)
                    end
                    if entry.line then
                        entry.line.Visible = S.espTracer
                        entry.line.Thickness = 1
                        entry.line.Color = color
                        entry.line.Transparency = 0.4
                        entry.line.From = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y)
                        entry.line.To = Vector2.new(botV.X, botV.Y)
                    end
                else
                    if entry.box then entry.box.Visible = false end
                    if entry.name then entry.name.Visible = false end
                    if entry.line then entry.line.Visible = false end
                end
            end
        end
    end
    for player, entry in pairs(espCache) do
        if not alive[player] then
            if entry.box then pcall(function() entry.box:Remove() end) end
            if entry.name then pcall(function() entry.name:Remove() end) end
            if entry.line then pcall(function() entry.line:Remove() end) end
            espCache[player] = nil
        end
    end
end)

Players.PlayerRemoving:Connect(function(player)
    local entry = espCache[player]
    if entry then
        if entry.box then pcall(function() entry.box:Remove() end) end
        if entry.name then pcall(function() entry.name:Remove() end) end
        if entry.line then pcall(function() entry.line:Remove() end) end
        espCache[player] = nil
    end
end)

