-- combat helpers
--------------------------------------------------------------------------
local function pickTarget()
    local cam = workspace.CurrentCamera
    local best, bestD
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LP and player.Character then
            local head = player.Character:FindFirstChild("Head")
            local hum = player.Character:FindFirstChildOfClass("Humanoid")
            if head and hum and hum.Health > 0 then
                local role = getRole(player)
                if S.aimTarget == "All" or role == S.aimTarget then
                    local _, on = cam:WorldToViewportPoint(head.Position)
                    local d = (head.Position - cam.CFrame.Position).Magnitude
                    if not bestD or d < bestD then best = head bestD = d end
                end
            end
        end
    end
    return best
end

RunService.RenderStepped:Connect(function()
    if not alive() then return end
    if S.combatV2 ~= false then return end
    if S.silentAim or S.aimbot then
        local target = pickTarget()
        if target then
            local char, hum = getChar()
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if root then
                local look = Vector3.new(target.Position.X, root.Position.Y, target.Position.Z)
                if (look - root.Position).Magnitude > 0.1 then
                    root.CFrame = CFrame.new(root.Position, look)
                end
            end
        end
    end
end)

task.spawn(function()
    while task.wait(0.1) do
        if not alive() then return end
        if S.combatV2 ~= false then return end
        if S.killAura then
            local char = LP.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if root then
                for _, player in ipairs(Players:GetPlayers()) do
                    if player ~= LP and player.Character then
                        local hrp = player.Character:FindFirstChild("HumanoidRootPart")
                        local hum = player.Character:FindFirstChildOfClass("Humanoid")
                        if hrp and hum and hum.Health > 0 then
                            if (hrp.Position - root.Position).Magnitude <= S.killRange then
                                local tool = char:FindFirstChildOfClass("Tool") or (LP.Backpack and LP.Backpack:FindFirstChildOfClass("Tool"))
                                if tool then pcall(function() tool:Activate() end) end
                            end
                        end
                    end
                end
            end
        end
    end
end)

