--------------------------------------------------------------------------
-- UI: rail tab look + selection
--------------------------------------------------------------------------
local function snapshotTab(tab)
    local bg = tab:FindFirstChild("Bg")
    local glow = tab:FindFirstChild("Glow")
    local tile = tab:FindFirstChild("Tile")
    local label = tab:FindFirstChild("Label")
    local stroke = bg and bg:FindFirstChildOfClass("UIStroke")
    return {
        bgTransparency = bg and bg.BackgroundTransparency or 1,
        glowTransparency = glow and glow.ImageTransparency or 1,
        glowColor = glow and glow.ImageColor3 or Color3.fromRGB(255, 122, 26),
        tileColor = tile and tile.ImageColor3 or Color3.fromRGB(39, 34, 30),
        tileTransparency = tile and tile.ImageTransparency or 0.4,
        labelColor = label and label.TextColor3 or Color3.fromRGB(163, 154, 144),
        strokeTransparency = stroke and stroke.Transparency or 1,
    }
end

local function applyLook(tab, look)
    if not look then return end
    local bg = tab:FindFirstChild("Bg")
    local glow = tab:FindFirstChild("Glow")
    local tile = tab:FindFirstChild("Tile")
    local label = tab:FindFirstChild("Label")
    local stroke = bg and bg:FindFirstChildOfClass("UIStroke")
    if bg then bg.BackgroundTransparency = look.bgTransparency end
    if stroke then stroke.Transparency = look.strokeTransparency end
    if glow then glow.ImageTransparency = look.glowTransparency glow.ImageColor3 = look.glowColor end
    if tile then tile.ImageTransparency = look.tileTransparency tile.ImageColor3 = look.tileColor end
    if label then label.TextColor3 = look.labelColor end
end

local railTabs = {}
for _, c in ipairs(CANVAS:GetChildren()) do
    if c:IsA("CanvasGroup") and c:FindFirstChild("Hit") then railTabs[#railTabs + 1] = c end
end

local activeLook, inactiveLook
for _, tab in ipairs(railTabs) do
    local bg = tab:FindFirstChild("Bg")
    local t = bg and bg.BackgroundTransparency or 1
    if t < 0.95 then
        activeLook = activeLook or snapshotTab(tab)
    else
        inactiveLook = inactiveLook or snapshotTab(tab)
    end
end
activeLook = activeLook or snapshotTab(railTabs[1])
inactiveLook = inactiveLook or activeLook

local headerLabels = {}
for _, c in ipairs(HEADER:GetChildren()) do
    if c:IsA("TextLabel") then headerLabels[#headerLabels + 1] = c end
end

local currentTab = ORDER[1]

local function setHeader(name)
    local info = HEADERS[name]
    if headerLabels[1] then headerLabels[1].Text = (info and info.title) or name end
    if headerLabels[2] then headerLabels[2].Text = (info and info.subtitle) or "" end
end

local function selectTab(name)
    if not BODY:FindFirstChild(name) then name = ORDER[1] end
    currentTab = name
    for _, c in ipairs(BODY:GetChildren()) do
        if c:IsA("CanvasGroup") then c.Visible = c.Name == name end
    end
    for _, tab in ipairs(railTabs) do
        applyLook(tab, tab.Name == name and activeLook or inactiveLook)
    end
    setHeader(name)
    task.defer(recomputeScrolls)
end

for _, tab in ipairs(railTabs) do
    local hit = tab:FindFirstChild("Hit")
    local tabName = tab.Name
    if hit and hit:IsA("GuiButton") then
        hit.MouseButton1Click:Connect(function() selectTab(tabName) end)
    end
end

local rowBase = {}
local headBase = {}
local bodyBase = {}
local cardBase = {}
local tabRows = {}
local tabBodies = {}
local function rowLabel(row)
    for _, c in ipairs(row:GetChildren()) do
        if c:IsA("TextLabel") and norm(c.Text) ~= "" then return norm(c.Text) end
    end
    local right = row:FindFirstChild("Right")
    local b = row:FindFirstChild("Button") or (right and right:FindFirstChild("Button", true))
    if b then
        for _, x in ipairs(b:GetDescendants()) do
            if x:IsA("TextLabel") and norm(x.Text) ~= "" then return norm(x.Text) end
        end
    end
    return ""
end
for _, tab in ipairs(BODY:GetChildren()) do
    if tab:IsA("CanvasGroup") then
        local rows, bodies = {}, {}
        for _, d in ipairs(tab:GetDescendants()) do
            if d:IsA("Frame") then
                if d.Name == "Row" and not d:GetAttribute("komaruHidden") then
                    rowBase[d] = d.Visible
                    rows[#rows + 1] = d
                elseif d.Name == "Head" then
                    headBase[d] = d.Visible
                elseif d.Name == "Body" then
                    bodyBase[d] = d.Visible
                    bodies[#bodies + 1] = d
                elseif d.Name == "Card" then
                    cardBase[d] = d.Visible
                end
            end
        end
        tabRows[tab.Name] = rows
        tabBodies[tab.Name] = bodies
    end
end

local prevClip = {}
local function clipsOf(tab)
    local pagesNode = tab:FindFirstChild("Pages")
    if not pagesNode then return {} end
    local clips = {}
    for _, c in ipairs(pagesNode:GetChildren()) do
        if c:IsA("CanvasGroup") and string.sub(c.Name, 1, 5) == "Clip_" then
            clips[#clips + 1] = c
        end
    end
    return clips
end

local function applySearch(raw)
    local q = norm(raw)
    local searching = q ~= ""
    local firstTab, currentHas
    for _, tab in ipairs(BODY:GetChildren()) do
        if tab:IsA("CanvasGroup") then
            local any = false
            for _, d in ipairs(tabRows[tab.Name] or {}) do
                local match = (not searching) or (string.find(rowLabel(d), q, 1, true) ~= nil)
                if match and rowBase[d] == false then match = false end
                d.Visible = match
                if searching and match then any = true end
            end
            local clips = clipsOf(tab)
            if #clips > 0 then
                if searching then
                    if not prevClip[tab.Name] then
                        for _, c in ipairs(clips) do
                            if c.Visible then prevClip[tab.Name] = c.Name end
                        end
                    end
                    local matchClip, bestCount = nil, 0
                    for _, c in ipairs(clips) do
                        local cnt = 0
                        for _, x in ipairs(c:GetDescendants()) do
                            if x:IsA("Frame") and x.Name == "Row" and x.Visible then cnt = cnt + 1 end
                        end
                        if cnt > bestCount then bestCount = cnt matchClip = c end
                    end
                    for _, c in ipairs(clips) do c.Visible = (c == matchClip) end
                else
                    local want = prevClip[tab.Name]
                    prevClip[tab.Name] = nil
                    local shown = false
                    for _, c in ipairs(clips) do
                        local on = want and c.Name == want
                        c.Visible = on
                        if on then shown = true end
                    end
                    if not shown and clips[1] then clips[1].Visible = true end
                end
            end
            for _, body in ipairs(tabBodies[tab.Name] or {}) do
                local hasRow = false
                for _, x in ipairs(body:GetDescendants()) do
                    if x:IsA("Frame") and x.Name == "Row" and x.Visible then hasRow = true break end
                end
                local head = body.Parent and body.Parent:FindFirstChild("Head")
                if searching then
                    body.Visible = hasRow
                    if head and headBase[head] ~= nil then head.Visible = hasRow end
                else
                    body.Visible = bodyBase[body] ~= false
                    if head and headBase[head] ~= nil then head.Visible = headBase[head] ~= false end
                end
            end
            for _, card in ipairs(tab:GetDescendants()) do
                if card:IsA("Frame") and card.Name == "Card" then
                    if searching then
                        local has = false
                        for _, x in ipairs(card:GetDescendants()) do
                            if x:IsA("Frame") and x.Name == "Row" and x.Visible then has = true break end
                        end
                        card.Visible = has
                    else
                        card.Visible = cardBase[card] ~= false
                    end
                end
            end
            if tab.Name == currentTab and searching then currentHas = any end
            if searching and any and not firstTab then firstTab = tab.Name end
        end
    end
    for _, rt in ipairs(railTabs) do
        if searching then
            local has = false
            for _, d in ipairs(tabRows[rt.Name] or {}) do
                if d.Visible then has = true break end
            end
            rt.Visible = has
        else
            rt.Visible = true
        end
    end
    if searching and firstTab and not currentHas and currentTab ~= firstTab then
        selectTab(firstTab)
    else
        task.defer(recomputeScrolls)
    end
end

