-- brand icon (Komaru anime avatar)
local ICON_B64 = ""
local ICON_ASSET
local function iconAsset()
    if ICON_ASSET ~= nil then return ICON_ASSET end
    ICON_ASSET = false
    if type(getcustomasset) == "function" then
        local name = "komaru_avatar_v2.png"
        if type(writefile) == "function" and type(base64_decode) == "function" then
            pcall(function() writefile(name, base64_decode(ICON_B64)) end)
        end
        local ok, url = pcall(getcustomasset, name)
        if ok and type(url) == "string" then ICON_ASSET = url end
    end
    return ICON_ASSET or nil
end

