local function toast(msg, iconImage)
    local TS = game:GetService("TweenService")
    local parentGui = (GUI and GUI.Parent) or game:GetService("CoreGui")
    local old = parentGui:FindFirstChild("KomaruToast")
    if old then pcall(function() old:Destroy() end) end
    local sg = Instance.new("ScreenGui")
    sg.Name = "KomaruToast"
    sg.ResetOnSpawn = false
    sg.IgnoreGuiInset = true
    sg.DisplayOrder = 2147483000
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    sg.Parent = parentGui

    local f = Instance.new("Frame")
    f.AnchorPoint = Vector2.new(0.5, 0)
    f.Position = UDim2.new(0.5, 0, 0, 18)
    f.Size = UDim2.new(0, 0, 0, 42)
    f.AutomaticSize = Enum.AutomaticSize.X
    f.BackgroundColor3 = Color3.fromRGB(22, 22, 24)
    f.BackgroundTransparency = 1
    f.BorderSizePixel = 0
    f.Parent = sg
    Instance.new("UICorner", f).CornerRadius = UDim.new(1, 0)
    local grad = Instance.new("UIGradient")
    grad.Color = ColorSequence.new(Color3.fromRGB(34, 34, 37), Color3.fromRGB(19, 19, 21))
    grad.Rotation = 90
    grad.Parent = f
    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(80, 80, 84)
    stroke.Transparency = 1
    stroke.Parent = f
    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, 14); pad.PaddingRight = UDim.new(0, 18)
    pad.PaddingTop = UDim.new(0, 8); pad.PaddingBottom = UDim.new(0, 8)
    pad.Parent = f
    local lay = Instance.new("UIListLayout")
    lay.FillDirection = Enum.FillDirection.Horizontal
    lay.VerticalAlignment = Enum.VerticalAlignment.Center
    lay.Padding = UDim.new(0, 10)
    lay.SortOrder = Enum.SortOrder.LayoutOrder
    lay.Parent = f

    if iconImage then
        local ic = Instance.new("ImageLabel")
        ic.BackgroundTransparency = 1
        ic.Size = UDim2.new(0, 22, 0, 22)
        ic.Image = iconImage
        ic.ImageTransparency = 1
        ic.LayoutOrder = 1
        ic.Parent = f
        TS:Create(ic, TweenInfo.new(0.2), { ImageTransparency = 0 }):Play()
    end
    local lbl = Instance.new("TextLabel")
    lbl.BackgroundTransparency = 1
    lbl.AutomaticSize = Enum.AutomaticSize.X
    lbl.Size = UDim2.new(0, 0, 0, 22)
    lbl.Font = Enum.Font.GothamMedium
    lbl.TextSize = 14
    lbl.TextColor3 = Color3.fromRGB(236, 236, 238)
    lbl.TextTransparency = 1
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.TextYAlignment = Enum.TextYAlignment.Center
    lbl.Text = msg
    lbl.LayoutOrder = 2
    lbl.Parent = f
    TS:Create(f, TweenInfo.new(0.2), { BackgroundTransparency = 0.04 }):Play()
    TS:Create(stroke, TweenInfo.new(0.2), { Transparency = 0.35 }):Play()
    TS:Create(lbl, TweenInfo.new(0.2), { TextTransparency = 0 }):Play()
    task.delay(1.8, function()
        TS:Create(f, TweenInfo.new(0.28), { BackgroundTransparency = 1 }):Play()
        TS:Create(stroke, TweenInfo.new(0.28), { Transparency = 1 }):Play()
        TS:Create(lbl, TweenInfo.new(0.28), { TextTransparency = 1 }):Play()
        task.wait(0.32)
        if sg and sg.Parent then pcall(function() sg:Destroy() end) end
    end)
end

