-- resize (drag the bottom-right corner)
do
    local resize = WIN:FindFirstChild("Resize")
    if resize and resize:IsA("GuiButton") then
        local rDrag, rStartDist, rStartScale, rmC, reC, lastUpd = nil, nil, nil, nil, nil, 0
        local cam = workspace.CurrentCamera
        local function recenter()
            local ap, as = ROOT.AbsolutePosition, ROOT.AbsoluteSize
            local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
            ROOT.Position = UDim2.new(ROOT.Position.X.Scale, ROOT.Position.X.Offset + (vp.X / 2 - (ap.X + as.X / 2)), ROOT.Position.Y.Scale, ROOT.Position.Y.Offset + (vp.Y / 2 - (ap.Y + as.Y / 2)))
        end
        resize.InputBegan:Connect(function(i)
            if i.UserInputType ~= Enum.UserInputType.MouseButton1 and i.UserInputType ~= Enum.UserInputType.Touch then return end
            local vp = cam.ViewportSize
            local c0 = Vector2.new(vp.X / 2, vp.Y / 2)
            rStartDist = math.max((Vector2.new(i.Position.X, i.Position.Y) - c0).Magnitude, 1)
            local s = ROOT:FindFirstChildOfClass("UIScale")
            rStartScale = s and s.Scale or 1
            rDrag = true
            lastUpd = 0
            if rmC then rmC:Disconnect() end
            if reC then reC:Disconnect() end
            rmC = UIS.InputChanged:Connect(function(ch)
                if not rDrag then return end
                if ch.UserInputType ~= Enum.UserInputType.MouseMovement and ch.UserInputType ~= Enum.UserInputType.Touch then return end
                local t = os.clock()
                if t - lastUpd < 0.05 then return end
                lastUpd = t
                local vp2 = cam.ViewportSize
                local cc = Vector2.new(vp2.X / 2, vp2.Y / 2)
                local dist = (Vector2.new(ch.Position.X, ch.Position.Y) - cc).Magnitude
                local s2 = ROOT:FindFirstChildOfClass("UIScale")
                if s2 then
                    local sc = math.clamp(rStartScale * (dist / rStartDist), 0.5, 2)
                    sc = math.floor(sc * 50 + 0.5) / 50
                    if math.abs(s2.Scale - sc) >= 0.019 then s2.Scale = sc end
                end
            end)
            reC = UIS.InputEnded:Connect(function(e)
                if e.UserInputType == Enum.UserInputType.MouseButton1 or e.UserInputType == Enum.UserInputType.Touch then
                    rDrag = false
                    if rmC then rmC:Disconnect() rmC = nil end
                    if reC then reC:Disconnect() reC = nil end
                    recenter()
                end
            end)
        end)
    end
end

-- drag
do
    local dragging, dragStart, dragPos, moveC, endC
    local function begin(input)
        dragging = true
        dragStart = input.Position
        dragPos = ROOT.Position
        if moveC then moveC:Disconnect() end
        if endC then endC:Disconnect() end
        moveC = UIS.InputChanged:Connect(function(ch)
            if not dragging then return end
            if ch.UserInputType ~= Enum.UserInputType.MouseMovement and ch.UserInputType ~= Enum.UserInputType.Touch then return end
            local d = ch.Position - dragStart
            ROOT.Position = UDim2.new(dragPos.X.Scale, dragPos.X.Offset + d.X, dragPos.Y.Scale, dragPos.Y.Offset + d.Y)
        end)
        endC = UIS.InputEnded:Connect(function(e)
            if e.UserInputType == Enum.UserInputType.MouseButton1 or e.UserInputType == Enum.UserInputType.Touch then
                dragging = false
                if moveC then moveC:Disconnect() moveC = nil end
                if endC then endC:Disconnect() endC = nil end
            end
        end)
    end
    local brand = SIDEBAR:FindFirstChild("Brand")
    if brand then
        brand.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then begin(i) end
        end)
    end
    HEADER.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then begin(i) end
    end)
end

