local ON_FILL = Color3.fromRGB(255, 122, 26)
local OFF_FILL = Color3.fromRGB(39, 34, 30)
local ON_GLOW = 0.60
local OFF_GLOW = 1.00

local function findDirectLabel(row, index)
    local list = {}
    for _, c in ipairs(row:GetChildren()) do
        if c:IsA("TextLabel") then list[#list + 1] = c end
    end
    return list[index or 1]
end

local function findRowLabel(row)
    for _, c in ipairs(row:GetChildren()) do
        if c:IsA("TextLabel") and c.Text ~= "" then return c end
    end
    return findDirectLabel(row, 1)
end

local function setToggleVisual(sw, on)
    local knob = sw:FindFirstChild("Knob")
    local fill = sw:FindFirstChild("Fill")
    local glow = sw:FindFirstChild("Glow")
    if knob then
        local w = sw.Size.X.Offset
        local kw = knob.Size.X.Offset
        local off = UDim2.new(0, 3, 0.5, 0)
        local on_ = UDim2.new(0, math.max(w - kw - 3, 3), 0.5, 0)
        knob.Position = on and on_ or off
    end
    if fill then fill.ImageColor3 = on and ON_FILL or OFF_FILL end
    if glow then glow.ImageTransparency = on and ON_GLOW or OFF_GLOW end
end

