function _G.KomaruSetSlider(track, frac)
    frac = math.clamp(frac, 0, 1)
    local bar = track:FindFirstChild("Bar")
    if not bar then return end
    local fill = bar:FindFirstChild("Fill")
    local knob = bar:FindFirstChild("Knob")
    if fill then fill.Size = UDim2.new(frac, 0, 1, 0) end
    if knob then knob.Position = UDim2.new(frac, 0, 0.5, 0) end
end

