local function numOr(setVal, setOn)
    return function(v)
        if type(v) == "number" then
            setVal(v)
            if setOn then setOn(true) end
        else
            if setOn then setOn(v) end
        end
    end
end

local function setFlag(key)
    return function(v) if type(v) == "boolean" then S[key] = v end end
end
local function setOnly(key)
    return function(v) if type(v) == "boolean" then S[key] = v elseif type(v) == "number" then S[key] = v end end
end

