-- behaviors: avoid murderer + anti aim + auto throw + auto farm
local lastFarm, lastAvoid = 0, 0
task.spawn(function()
    while task.wait(0.12) do
        if not alive() then return end
        local char, hum = getChar()
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local now = os.clock()
        if root then
            if S.avoidMurderer and now - lastAvoid > 0.6 then
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LP and p.Character and getRole(p) == "Murderer" then
                        local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                        if hrp and (hrp.Position - root.Position).Magnitude < 22 then
                            local away = root.Position - hrp.Position
                            if away.Magnitude > 0.1 then
                                local safe = root.Position + away.Unit * 45 + Vector3.new(0, 2, 0)
                                pcall(function()
                                    root.CFrame = CFrame.new(safe, Vector3.new(hrp.Position.X, safe.Y, hrp.Position.Z))
                                    root.AssemblyLinearVelocity = Vector3.zero
                                end)
                                lastAvoid = now
                            end
                            break
                        end
                    end
                end
            end
            if S.autoThrow then
                local tool = char:FindFirstChildOfClass("Tool")
                if tool and string.find(string.lower(tool.Name), "knife", 1, true) then
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= LP and p.Character then
                            local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                            local h2 = p.Character:FindFirstChildOfClass("Humanoid")
                            if hrp and h2 and h2.Health > 0 and (hrp.Position - root.Position).Magnitude < 16 then
                                pcall(function() tool:Activate() end)
                            end
                        end
                    end
                end
            end
            -- auto farm motion handled by the smooth "fly to coin" loop below
        end
    end
end)

-- smooth auto farm: glide toward the nearest coin (instead of teleporting)
local coinCache = {}
task.spawn(function()
    while task.wait(0.35) do
        if not alive() then return end
        local list = {}
        for _, d in ipairs(workspace:GetDescendants()) do
            if d:IsA("BasePart") then
                local n = string.lower(d.Name)
                local pos = d.Position
                local sane = pos.X == pos.X and pos.Y == pos.Y and pos.Z == pos.Z
                    and math.abs(pos.Y) < 5000 and math.abs(pos.X) < 100000 and math.abs(pos.Z) < 100000
                if sane and (string.find(n, "coin", 1, true) or string.find(n, "candy", 1, true) or string.find(n, "cash", 1, true) or string.find(n, "money", 1, true)) then
                    list[#list + 1] = d
                end
            end
        end
        coinCache = list
    end
end)

RunService.RenderStepped:Connect(function(dt)
    if not alive() then return end
    if not S.autoFarm then return end
    local char, hum = getChar()
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return end
    if S.smartPause and nearestPlayer(45) then return end
    if S.farmPauseUntil and tick() < S.farmPauseUntil then return end
    local best, bestD
    for _, d in ipairs(coinCache) do
        if d.Parent then
            local dist = (d.Position - root.Position).Magnitude
            if dist < 600 and (not bestD or dist < bestD) then best = d bestD = dist end
        end
    end
    if not best then return end
    local speed = math.clamp((S.farmSpeed or 8) * 16, 24, 260)
    local goal = best.Position + Vector3.new(0, 3, 0)
    local delta = goal - root.Position
    if delta.Magnitude >= 1.2 then
        local stepv = delta.Unit * math.min(speed * dt, delta.Magnitude)
        local np = root.Position + stepv
        root.CFrame = CFrame.new(np, Vector3.new(goal.X, np.Y, goal.Z))
    end
    root.AssemblyLinearVelocity = Vector3.zero
end)

local aaPhase = 0
local function rotateY(v, deg)
    local r = math.rad(deg)
    local c, s = math.cos(r), math.sin(r)
    return Vector3.new(v.X * c - v.Z * s, v.Y, v.X * s + v.Z * c)
end
RunService.RenderStepped:Connect(function(dt)
    if not alive() then return end
    if not S.antiAim or S.aimbot or S.silentAim then return end
    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local cam = workspace.CurrentCamera
    if not (root and cam) then return end
    local mode = string.lower(tostring(S.antiAimMode or S.aaMode or "spin"))
    local base = Vector3.new(cam.CFrame.LookVector.X, 0, cam.CFrame.LookVector.Z)
    if base.Magnitude < 0.01 then base = Vector3.new(0, 0, -1) end
    local ang
    if string.find(mode, "back", 1, true) then
        ang = 180
    elseif string.find(mode, "side", 1, true) then
        ang = 90
    elseif string.find(mode, "jitter", 1, true) then
        aaPhase = aaPhase + dt * 10
        ang = (math.floor(aaPhase) % 2 == 0) and 90 or -90
    elseif string.find(mode, "random", 1, true) then
        ang = (math.sin(tick() * 3.7) > 0) and 60 or -120
    else
        aaPhase = aaPhase + dt * (S.aaSpeed or 9) * 60
        ang = aaPhase % 360
    end
    root.CFrame = CFrame.new(root.Position, root.Position + rotateY(base, ang))
end)

local function toggleFeature(label, on)
    local fn = FEATURES[label]
    if fn then pcall(fn, on) end
end
local function valueFeature(label, val)
    local fn = FEATURES[label]
    if fn then pcall(fn, val) end
end

local TOGGLE_SYNC = {}
local TOGGLE_STATE = {}
local function wireToggle(row, label)
    local right = row:FindFirstChild("Right")
    local sw = right and (right:FindFirstChild("Switch") or right:FindFirstChild("Switch", true))
    local hit = row:FindFirstChild("Hit")
    if not (sw and hit) then return end
    local state = false
    local fill = sw:FindFirstChild("Fill")
    if fill and fill.ImageColor3.R > 0.5 then state = true end
    local function apply(v)
        state = v and true or false
        setToggleVisual(sw, state)
    end
    TOGGLE_SYNC[label] = apply
    TOGGLE_STATE[label] = function() return state end
    hit.MouseButton1Click:Connect(function()
        apply(not state)
        toggleFeature(label, state)
    end)
end

local function wireSlider(row, label, onChange)
    local track = row:FindFirstChild("Track")
        or (row:FindFirstChild("Right") and row.Right:FindFirstChild("Track", true))
    if not track then return end
    local valueLabel = findDirectLabel(row, 2)
    local bar = track:FindFirstChild("Bar")
    local knob = bar and bar:FindFirstChild("Knob")
    local frac = knob and knob.Position.X.Scale or 0
    local range = SLIDER_RANGE[label] or { 0, 100, 1 }
    local function computeFrac(x)
        local ax = track.AbsolutePosition.X
        local aw = track.AbsoluteSize.X
        if aw <= 0 then return frac end
        return math.clamp((x - ax) / aw, 0, 1)
    end
    local function setFrac(f)
        frac = f
        _G.KomaruSetSlider(track, frac)
        local val = range[1] + frac * (range[2] - range[1])
        local step = range[3]
        val = math.floor(val / step + 0.5) * step
        if valueLabel then
            if step < 1 then valueLabel.Text = string.format("%.1f", val) else valueLabel.Text = tostring(math.floor(val + 0.5)) end
        end
        onChange(val)
    end
    local dragging = false
    track.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            setFrac(computeFrac(input.Position.X))
        end
    end)
    UIS.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            setFrac(computeFrac(input.Position.X))
        end
    end)
    UIS.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)
end

local function wireButton(row, label)
    local button = row:FindFirstChild("Button")
        or (row:FindFirstChild("Right") and row.Right:FindFirstChild("Button", true))
    if not button then return end
    button.MouseButton1Click:Connect(function()
        local fn = FEATURES[label]
        if fn then pcall(fn, true) end
    end)
end

local function wireDropdown(row, label)
    local box = row:FindFirstChild("Box")
        or (row:FindFirstChild("Right") and row.Right:FindFirstChild("Box", true))
    if not box then return end
    local options = DROPDOWNS[label] or {}
    local valueLabel
    for _, c in ipairs(box:GetChildren()) do
        if c:IsA("TextLabel") then valueLabel = valueLabel or c end
    end
    local idx = 1
    if valueLabel then
        for i, o in ipairs(options) do
            if o == valueLabel.Text then idx = i break end
        end
    end
    box.MouseButton1Click:Connect(function()
        if #options == 0 then return end
        idx = idx % #options + 1
        if valueLabel then valueLabel.Text = options[idx] end
        valueFeature(label, options[idx])
    end)
end

local function wireKeybind(row, label)
    local right = row:FindFirstChild("Right")
    local bind = right and (right:FindFirstChild("Bind") or right:FindFirstChild("Bind", true))
    if not bind then return end
    local faceLabel
    for _, d in ipairs(bind:GetDescendants()) do
        if d:IsA("TextLabel") then faceLabel = d break end
    end
    bind.MouseButton1Click:Connect(function()
        if faceLabel then faceLabel.Text = "..." end
        local conn
        conn = UIS.InputBegan:Connect(function(input, gpe)
            if gpe then return end
            if input.UserInputType == Enum.UserInputType.Keyboard and faceLabel then
                faceLabel.Text = input.KeyCode.Name
                S.binds = S.binds or {}
                S.binds[label] = input.KeyCode.Name
                conn:Disconnect()
            end
        end)
    end)
end

local function wireSwatch(row, label, swatch)
    local right = row:FindFirstChild("Right")
    local hex
    if right then
        for _, c in ipairs(right:GetDescendants()) do
            if c:IsA("TextLabel") and string.find(c.Text, "#", 1, true) then hex = c break end
        end
    end
    local palette = {
        Color3.fromRGB(120, 220, 255), Color3.fromRGB(255, 255, 255),
        Color3.fromRGB(255, 96, 96), Color3.fromRGB(120, 255, 150),
        Color3.fromRGB(255, 205, 100), Color3.fromRGB(200, 130, 255),
        Color3.fromRGB(255, 130, 205), Color3.fromRGB(255, 60, 60),
    }
    if type(S.colors) ~= "table" then S.colors = {} end
    local idx = 1
    local current = S.colors[label]
    if not (typeof(current) == "Color3") and hex then
        local r, g, b = string.match(hex.Text or "", "#(%x%x)(%x%x)(%x%x)")
        if r then
            current = Color3.fromRGB(tonumber(r, 16), tonumber(g, 16), tonumber(b, 16))
            S.colors[label] = current
        end
    end
    if typeof(current) == "Color3" then
        for i, c in ipairs(palette) do
            if math.abs(c.R - current.R) < 0.01 and math.abs(c.G - current.G) < 0.01 and math.abs(c.B - current.B) < 0.01 then
                idx = i
                break
            end
        end
    end
    local function apply(col)
        S.colors[label] = col
        if hex then
            hex.Text = string.format("#%02X%02X%02X  80%%",
                math.floor(col.R * 255 + 0.5), math.floor(col.G * 255 + 0.5), math.floor(col.B * 255 + 0.5))
        end
        local fn = FEATURES[label]
        if fn then pcall(fn, col) end
    end
    FEATURES[label] = FEATURES[label] or apply
    swatch.MouseButton1Click:Connect(function()
        idx = idx % #palette + 1
        apply(palette[idx])
    end)
end

local function wireSection(head, bodyContent)
    local hit = head:FindFirstChild("Hit")
    if hit and hit:IsA("GuiButton") and bodyContent then
        hit.MouseButton1Click:Connect(function()
            bodyContent.Visible = not bodyContent.Visible
        end)
    end
end

local counts = { toggle = 0, slider = 0, button = 0, dropdown = 0, keybind = 0, section = 0 }

local function wireTab(tab)
    local tabName = tab.Name
    for _, d in ipairs(tab:GetDescendants()) do
        if d:IsA("Frame") and d.Name == "Head" and d:FindFirstChild("Hit") and d.Parent and d.Parent:FindFirstChild("Body") then
            counts.section = counts.section + 1
            wireSection(d, d.Parent:FindFirstChild("Body"))
        end
    end
    for _, d in ipairs(tab:GetDescendants()) do
        if d:IsA("Frame") and d.Name == "Row" then
            local lbl = findRowLabel(d)
            local label = norm(lbl and lbl.Text)
            if label == "" then
                local rb = d:FindFirstChild("Right")
                local b = d:FindFirstChild("Button") or (rb and rb:FindFirstChild("Button", true))
                if b then
                    for _, x in ipairs(b:GetDescendants()) do
                        if x:IsA("TextLabel") and norm(x.Text) ~= "" then label = norm(x.Text) break end
                    end
                end
            end
            if label ~= "" then
                local right = d:FindFirstChild("Right")
                local function inRight(name)
                    if not right then return nil end
                    return right:FindFirstChild(name) or right:FindFirstChild(name, true)
                end
                local sw = d:FindFirstChild("Switch") or inRight("Switch")
                local track = d:FindFirstChild("Track") or inRight("Track")
                local box = d:FindFirstChild("Box") or inRight("Box")
                local button = d:FindFirstChild("Button") or inRight("Button")
                local bind = d:FindFirstChild("Bind") or inRight("Bind")
                local swatch = d:FindFirstChild("Swatch") or inRight("Swatch")
                if sw then
                    counts.toggle = counts.toggle + 1
                    pcall(wireToggle, d, label)
                elseif track then
                    counts.slider = counts.slider + 1
                    pcall(wireSlider, d, label, function(v) valueFeature(label, v) end)
                elseif box then
                    counts.dropdown = counts.dropdown + 1
                    pcall(wireDropdown, d, label)
                elseif swatch then
                    counts.button = counts.button + 1
                    pcall(wireSwatch, d, label, swatch)
                elseif button then
                    counts.button = counts.button + 1
                    pcall(wireButton, d, label)
                elseif bind then
                    counts.keybind = counts.keybind + 1
                    pcall(wireKeybind, d, label)
                end
            end
        end
    end
end

for _, tab in ipairs(BODY:GetChildren()) do
    if tab:IsA("CanvasGroup") then
        wireTab(tab)
    end
end
task.defer(recomputeScrolls)
task.delay(0.5, recomputeScrolls)
task.delay(1.5, recomputeScrolls)

local function wireSubTabs(tab)
    local pagesNode = tab:FindFirstChild("Pages")
    local subbar = tab:FindFirstChild("SubBar")
    if not (pagesNode and subbar) then return end
    local row = subbar:FindFirstChild("Row", true)
    if not row or not row:IsA("Frame") then return end
    local clips = {}
    for _, c in ipairs(pagesNode:GetChildren()) do
        if string.sub(c.Name, 1, 5) == "Clip_" then clips[string.sub(c.Name, 6)] = c end
    end
    if next(clips) == nil then return end
    pcall(function()
        row.Visible = true
        row.Position = UDim2.new(0, 6, 0, 0)
        row.Size = UDim2.new(1, -12, 1, 0)
        local layout = row:FindFirstChildOfClass("UIListLayout")
        if not layout then
            layout = Instance.new("UIListLayout")
            layout.FillDirection = Enum.FillDirection.Horizontal
            layout.HorizontalAlignment = Enum.HorizontalAlignment.Left
            layout.VerticalAlignment = Enum.VerticalAlignment.Center
            layout.Padding = UDim.new(0, 6)
            layout.SortOrder = Enum.SortOrder.LayoutOrder
            layout.Parent = row
        end
        local shell = subbar:FindFirstChild("Shell")
        if shell then
            shell.Position = UDim2.new(0, 0, 0, 0)
            shell.Size = UDim2.new(1, 0, 1, 0)
        end
        local pill = subbar:FindFirstChild("Pill", true)
        local buttons = {}
        for _, c in ipairs(row:GetDescendants()) do
            if c:IsA("GuiButton") then buttons[#buttons + 1] = c end
        end
        local function placePill(btn)
            if not (pill and btn) then return end
            pcall(function()
                pill.Size = UDim2.new(0, btn.AbsoluteSize.X, 0, 30)
                pill.Position = UDim2.new(0, btn.AbsolutePosition.X - subbar.AbsolutePosition.X, 0.5, -pill.Size.Y.Offset / 2)
            end)
        end
        local function show(name)
            for cn, clip in pairs(clips) do
                pcall(function() clip.Visible = cn == name end)
            end
            task.defer(recomputeScrolls)
        end
        for i, b in ipairs(buttons) do
            local text = b.Name
            local lbl = b:FindFirstChild("Label")
            if lbl and lbl:IsA("TextLabel") and lbl.Text ~= "" then text = lbl.Text end
            b.LayoutOrder = i
            b.AutoButtonColor = false
            pcall(function() b.Size = UDim2.new(0, math.max(52, #text * 8 + 24), 0, 30) end)
            if lbl then
                pcall(function()
                    lbl.Size = UDim2.new(1, 0, 1, 0)
                    lbl.Position = UDim2.new(0, 0, 0, 0)
                    lbl.TextXAlignment = Enum.TextXAlignment.Center
                end)
            end
            b.MouseButton1Click:Connect(function()
                show(b.Name)
                placePill(b)
            end)
        end
        if buttons[1] then
            show(buttons[1].Name)
            task.defer(function() placePill(buttons[1]) end)
            task.delay(0.3, function() placePill(buttons[1]) end)
        end
    end)
end

for _, tab in ipairs(BODY:GetChildren()) do
    if tab:IsA("CanvasGroup") then wireSubTabs(tab) end
end

-- ==========================================================================
-- Komaru extended logic (movement / combat / troll / fling / farm / server)
-- ==========================================================================
local TweenService = game:GetService("TweenService")
local TeleportService = game:GetService("TeleportService")
local HttpService = game:GetService("HttpService")

local EXTRA = {
    spin = false, spinSpeed = 10,
    camFlick = false, flickAngle = 12,
    antiFling = false,
    invisible = false,
    speedGlitch = false, glitchSpeed = 60,
    wallHop = false,
    orbit = false, orbitSpeed = 3, orbitRadius = 7, orbitTarget = nil,
    hump = false,
    clickFling = false, touchFling = false, flingPanel = false,
    autoEmote = false,
    autoShootMurder = false,
    killAll = false,
    killGunPlayers = false,
    autoPickupGun = false, pickupDistance = 10,
    autoFlingSheriff = false,
    fovCircle = false, fovSize = 90, fovTransparency = 0.6,
    espShowMurderer = true, espShowSheriff = true, espShowInnocent = true,
    bright = 3,
    bhopPower = 60,
    spoofMove = false, spoofVelocity = false,
    autoRespawnFullBag = false, shootMurderFullBag = false, autoRejoinKick = false,
    inventoryValues = false, tradeValue = false,
    farmSpeed = 20, tpDelay = 3,
    autoGun = false, autoKill = false, wallCheck = false,
    predict = 0.13, lead = 100, maxDist = 0, autoRange = 0, autoMinChance = 0,
    aimTargetMode = "Murderer",
    aaMode = "spin", aaSpeed = 9, smartPause = false, humpDur = 0,
    autoOpen = false, murderFarm = false, autoThrow = false, noParticles = false,
}
for k, v in pairs(EXTRA) do if S[k] == nil then S[k] = v end end

local function murdererPlayer()
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p.Character and getRole(p) == "Murderer" then return p end
    end
end

local function nearestPlayer(maxD)
    local mr = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
    if not mr then return nil end
    local best, bd
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p.Character then
            local r = p.Character:FindFirstChild("HumanoidRootPart")
            if r then
                local d = (r.Position - mr.Position).Magnitude
                if (not bd or d < bd) and (not maxD or d <= maxD) then best = p bd = d end
            end
        end
    end
    return best
end

-- ---- FLING ----------------------------------------------------------------
local function flingPlayer(target)
    if not target then return end
    local tchar = target.Character
    local trp = tchar and tchar:FindFirstChild("HumanoidRootPart")
    local mchar = LP.Character
    local mrp = mchar and mchar:FindFirstChild("HumanoidRootPart")
    if not (trp and mrp) then return end
    local saved = mrp.CFrame
    local _, hum = getChar()
    pcall(function()
        for _, p in ipairs(tchar:GetDescendants()) do
            if p:IsA("BasePart") then p.CanCollide = true p.Massless = false end
        end
        mrp.CFrame = trp.CFrame * CFrame.new(0, 0, -1.5)
        local weld = Instance.new("WeldConstraint")
        weld.Part0 = mrp
        weld.Part1 = trp
        weld.Parent = mrp
        local bv = Instance.new("BodyVelocity")
        bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
        bv.P = 3000
        bv.Velocity = Vector3.zero
        bv.Parent = mrp
        task.wait(0.03)
        bv.Velocity = Vector3.new(1e6, 1e6, 1e6)
        task.delay(0.16, function()
            pcall(function() bv:Destroy() end)
            pcall(function() weld:Destroy() end)
            -- forcibly return OURSELVES to where we were, so we never fly to space
            if mrp and mrp.Parent then
                pcall(function()
                    mrp.CFrame = saved
                    mrp.AssemblyLinearVelocity = Vector3.zero
                    mrp.AssemblyAngularVelocity = Vector3.zero
                end)
            end
            if hum then hum.PlatformStand = false end
        end)
    end)
end

-- safety net: if the local player ever ends up absurdly far/out of world, snap back
local lastSafe = nil
RunService.Heartbeat:Connect(function()
    if not alive() then return end
    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return end
    local p = root.Position
    if p.Y > -300 and p.Y < 10000 and p.Magnitude < 1e6 then
        lastSafe = p
    elseif p.Y < -300 or p.Y > 1e5 or p.Magnitude > 1e6 then
        if lastSafe then
            pcall(function() root.CFrame = CFrame.new(lastSafe) end)
            pcall(function() root.AssemblyLinearVelocity = Vector3.zero end)
            if S.autoFarm then S.farmPauseUntil = tick() + 2 end
        end
    end
end)

local invSaved = {}
local function setInvisible(on)
    local char = LP.Character
    if not char then return end
    if on then
        for _, d in ipairs(char:GetDescendants()) do
            if d:IsA("BasePart") or d:IsA("Decal") then
                if invSaved[d] == nil then invSaved[d] = d.Transparency end
                pcall(function() d.Transparency = 1 end)
            end
        end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            if invSaved.__nameDisp == nil then invSaved.__nameDisp = hum.NameDisplayDistance end
            pcall(function() hum.NameDisplayDistance = 0 end)
        end
    else
        local nameDisp = invSaved.__nameDisp
        for d, t in pairs(invSaved) do
            if typeof(d) == "Instance" and d.Parent then
                pcall(function() d.Transparency = t end)
            end
        end
        invSaved = {}
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum and nameDisp ~= nil then pcall(function() hum.NameDisplayDistance = nameDisp end) end
    end
end

-- ---- movement / troll / combat loops --------------------------------------
local orbitAngle = 0
local humpUntil = 0
RunService.RenderStepped:Connect(function(dt)
    if not alive() then return end
    local char, hum = getChar()
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return end
    if S.spin then
        root.CFrame = root.CFrame * CFrame.Angles(0, math.rad(S.spinSpeed) * dt * 12, 0)
    end
    if S.camFlick then
        local cam = workspace.CurrentCamera
        if cam then cam.CFrame = cam.CFrame * CFrame.Angles(0, math.rad(S.flickAngle) * math.sin(tick() * 6) * 0.1, 0) end
    end
    if S.orbit then
        local tgt = murdererPlayer() or nearestPlayer()
        if tgt and tgt.Character then
            local tr = tgt.Character:FindFirstChild("HumanoidRootPart")
            if tr then
                orbitAngle = orbitAngle + dt * S.orbitSpeed
                local pos = tr.Position + Vector3.new(math.cos(orbitAngle) * S.orbitRadius, 2, math.sin(orbitAngle) * S.orbitRadius)
                root.CFrame = CFrame.new(pos, tr.Position)
            end
        end
    end
    if S.hump then
        if not humpUntil then humpUntil = 0 end
        local dur = tonumber(S.humpDur) or 0
        if dur > 0 then
            if humpUntil == 0 then humpUntil = tick() + dur end
            if tick() > humpUntil then
                humpUntil = 0
                S.hump = false
                toggleFeature("click hump", false)
                return
            end
        else
            humpUntil = 0
        end
        local tgt = nearestPlayer(6)
        if tgt and tgt.Character then
            local tr = tgt.Character:FindFirstChild("HumanoidRootPart")
            if tr then root.CFrame = tr.CFrame * CFrame.new(0, math.sin(tick() * 28) * 0.6, -1.2) end
        end
    else
        humpUntil = 0
    end
end)

task.spawn(function()
    local lastInv = nil
    local lastNoParts, lastPrompt = 0, 0
    while task.wait(0.2) do
        if not alive() then return end
        local char, hum = getChar()
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if hum and lastInv ~= S.invisible then
            lastInv = S.invisible
            setInvisible(S.invisible)
        end
        if S.touchFling then
            local t = nearestPlayer(4)
            if t then flingPlayer(t) end
        end
        if S.autoFlingSheriff then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LP and p.Character and getRole(p) == "Sheriff" then flingPlayer(p) end
            end
        end
        if S.flingPanel then
            local t = murdererPlayer() or nearestPlayer(60)
            if t then flingPlayer(t) end
        end
        if S.speedGlitch and hum then
            hum.WalkSpeed = S.glitchSpeed
            task.wait(0.05)
            hum.WalkSpeed = 16
        end
        if S.bhop and UIS:IsKeyDown(Enum.KeyCode.Space) and hum then
            hum:ChangeState(Enum.HumanoidStateType.Jumping)
        end
        if S.noParticles and tick() - lastNoParts > 1 then
            lastNoParts = tick()
            for _, d in ipairs(workspace:GetDescendants()) do
                if d:IsA("ParticleEmitter") and d.Enabled then d.Enabled = false end
            end
        end
        if S.autoOpen and root and tick() - lastPrompt > 0.6 then
            lastPrompt = tick()
            for _, d in ipairs(workspace:GetDescendants()) do
                if d:IsA("ProximityPrompt") and d.Enabled then
                    local part = d.Parent
                    if part and part:IsA("BasePart") and (part.Position - root.Position).Magnitude < 14 then
                        pcall(function() d:InputHoldBegin() end)
                        task.delay(math.max(d.HoldDuration, 0.05), function() pcall(function() d:InputHoldEnd() end) end)
                    end
                end
            end
        end
    end
end)

task.spawn(function()
    while task.wait(0.12) do
        if not alive() then return end
        local char, hum = getChar()
        if char then
            local root = char:FindFirstChild("HumanoidRootPart")
            local tool = char:FindFirstChildOfClass("Tool")
            local toolName = tool and string.lower(tool.Name) or ""
            if (S.autoShootMurder or S.wallbang) and tool and string.find(toolName, "gun", 1, true) then
                local m = murdererPlayer()
                local h = m and m.Character and m.Character:FindFirstChild("Head")
                if h and root then
                    local aim = h.Position
                    if S.predict and S.predict > 0 then aim = aim + h.AssemblyLinearVelocity * S.predict end
                    local look = Vector3.new(aim.X, root.Position.Y, aim.Z)
                    if (look - root.Position).Magnitude > 0.1 then
                        root.CFrame = CFrame.new(root.Position, look)
                    end
                    local canShoot = true
                    if S.wallCheck and not S.wallbang then
                        local params = RaycastParams.new()
                        params.FilterType = Enum.RaycastFilterType.Exclude
                        params.FilterDescendantsInstances = { LP.Character, m.Character }
                        local hit = workspace:Raycast(root.Position, aim - root.Position, params)
                        canShoot = (hit == nil)
                    end
                    if canShoot then pcall(function() tool:Activate() end) end
                end
            end
            if (S.killAll or S.killGunPlayers or S.murderFarm) and tool and string.find(toolName, "knife", 1, true) and root then
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LP and p.Character then
                        local r = p.Character:FindFirstChild("HumanoidRootPart")
                        local hh = p.Character:FindFirstChildOfClass("Humanoid")
                        if r and hh and hh.Health > 0 and (r.Position - root.Position).Magnitude < 14 then
                            local doIt = S.killAll or S.murderFarm
                            if not doIt and S.killGunPlayers then
                                local role = getRole(p)
                                doIt = (role == "Sheriff" or role == "Murderer")
                            end
                            if doIt then pcall(function() tool:Activate() end) end
                        end
                    end
                end
            end
            if S.autoThrow and tool and string.find(toolName, "knife", 1, true) and root then
                local t = murdererPlayer() or nearestPlayer(55)
                local th = t and t.Character and t.Character:FindFirstChild("Head")
                if th and (th.Position - root.Position).Magnitude < 55 then
                    local look = Vector3.new(th.Position.X, root.Position.Y, th.Position.Z)
                    if (look - root.Position).Magnitude > 0.1 then
                        root.CFrame = CFrame.new(root.Position, look)
                    end
                    pcall(function() tool:Activate() end)
                end
            end
            if S.autoPickupGun then
                local rootp = char:FindFirstChild("HumanoidRootPart")
                for _, d in ipairs(workspace:GetDescendants()) do
                    if d:IsA("Tool") and string.find(string.lower(d.Name), "gun", 1, true) then
                        local handle = d:FindFirstChild("Handle")
                        if handle and rootp and (handle.Position - rootp.Position).Magnitude < S.pickupDistance then
                            pcall(function() d.Parent = char end)
                        end
                    end
                end
            end
            if S.autoRespawnFullBag and hum and hum.Health > 0 then
                local bag = LP:FindFirstChild("leaderstats") and LP.leaderstats:FindFirstChild("Coins")
                if bag and bag.Value and bag.Value >= 10 then hum.Health = 0 end
            end
        end
    end
end)

-- click fling / click hump
UIS.InputBegan:Connect(function(input, gpe)
    if gpe then return end
    if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
    if not (S.clickFling or S.hump) then return end
    local cam = workspace.CurrentCamera
    local ray = cam:ViewportPointToRay(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
    local params = RaycastParams.new()
    params.FilterDescendantsInstances = { LP.Character }
    params.FilterType = Enum.RaycastFilterType.Exclude
    local hit = workspace:Raycast(ray.Origin, ray.Direction * 2000, params)
    if not hit then return end
    local model = hit.Instance:FindFirstAncestorOfClass("Model")
    local plr = model and Players:GetPlayerFromCharacter(model)
    if plr and plr ~= LP then
        if S.clickFling then flingPlayer(plr) end
        if S.hump then S.orbitTarget = plr.Name end
    end
end)

