-- FOV circle draw
local fovCircle
RunService.RenderStepped:Connect(function()
    if not alive() then return end
    if S.fovCircle then
        if not fovCircle then fovCircle = newDraw("Circle") end
        if fovCircle then
            local cam = workspace.CurrentCamera
            fovCircle.Visible = true
            fovCircle.Position = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
            fovCircle.Radius = S.fovSize
            fovCircle.Thickness = 1
            fovCircle.Color = Color3.fromRGB(255, 122, 26)
            fovCircle.Transparency = S.fovTransparency
            fovCircle.NumSides = 64
        end
    elseif fovCircle then
        pcall(function() fovCircle:Remove() end)
        fovCircle = nil
    end
end)

-- ---- FEATURES: teleport ---------------------------------------------------
local function tpTo(part)
    local _, hum = getChar()
    local root = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
    if root and part then pcall(function()
        root.CFrame = part.CFrame + Vector3.new(0, 2, 0)
        root.AssemblyLinearVelocity = Vector3.zero
    end) end
end
local function rolePart(role)
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p.Character and getRole(p) == role then
            return p.Character:FindFirstChild("HumanoidRootPart")
        end
    end
end
FEATURES["tp murderer"] = function() tpTo(rolePart("Murderer")) end
FEATURES["tp sheriff"] = function() tpTo(rolePart("Sheriff")) end
FEATURES["tp map"] = function()
    local part = workspace:FindFirstChild("Map") or workspace
    if part and part ~= workspace then tpTo(part:FindFirstChildWhichIsA("BasePart")) end
end
FEATURES["tp lobby"] = function()
    local lobby = workspace:FindFirstChild("Lobby")
    if lobby then tpTo(lobby:FindFirstChildWhichIsA("BasePart")) end
end

-- ---- FEATURES: server -----------------------------------------------------
local function fetchServers()
    local url = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100"
    local ok, res = pcall(function() return game:HttpGet(url) end)
    if not ok or not res then return {} end
    local ok2, data = pcall(function() return HttpService:JSONDecode(res) end)
    if ok2 and data and data.data then return data.data end
    return {}
end
FEATURES["copy job id"] = function()
    pcall(function() setclipboard(game.JobId) end)
    toast("Job ID скопирован: " .. tostring(game.JobId):sub(1, 8) .. "...")
end
FEATURES["rejoin server"] = function()
    toast("Переподключение к серверу...")
    pcall(function() TeleportService:Teleport(game.PlaceId, LP) end)
end
FEATURES["server hop"] = function()
    toast("Ищу новый сервер...")
    local servers = fetchServers()
    for _, s in ipairs(servers) do
        if s.id ~= game.JobId and s.playing < s.maxPlayers then
            pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, s.id, LP) end)
            return
        end
    end
    toast("Свободных серверов не найдено")
end
FEATURES["join small server"] = function()
    toast("Ищу маленький сервер...")
    local servers = fetchServers()
    local best
    for _, s in ipairs(servers) do
        if s.id ~= game.JobId and (not best or s.playing < best.playing) then best = s end
    end
    if best then pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, best.id, LP) end) end
end
FEATURES["shot murder"] = function()
    local char = LP.Character
    local tool = char and char:FindFirstChildOfClass("Tool")
    local m = murdererPlayer()
    local hum = tool and m and m.Character and m.Character:FindFirstChildOfClass("Humanoid")
    if not (tool and m and hum) then toast("Цель не найдена") return end
    local name = string.lower(tool.Name)
    if not string.find(name, "gun", 1, true) then toast("Нужен пистолет") return end
    local head = m.Character:FindFirstChild("Head")
    if head then
        local root = char.HumanoidRootPart
        local look = Vector3.new(head.Position.X, root.Position.Y, head.Position.Z)
        if (look - root.Position).Magnitude > 0.1 then root.CFrame = CFrame.new(root.Position, look) end
    end
    pcall(function() tool:Activate() end)
end

local function previewFx(kind)
    local cam = workspace.CurrentCamera
    if not cam then return end
    local vp = cam.ViewportSize
    local line = Drawing.new("Line")
    line.Thickness = 2
    line.Transparency = 1
    line.Color = (kind == "knife") and Color3.fromRGB(255, 90, 90) or (kind == "gun" and Color3.fromRGB(120, 200, 255) or Color3.fromRGB(255, 170, 60))
    line.From = Vector2.new(vp.X / 2, vp.Y + 10)
    local to = Vector2.new(vp.X / 2 + math.random(-250, 250), vp.Y / 2 + math.random(-180, 180))
    line.To = line.From
    task.spawn(function()
        local t0 = tick()
        while tick() - t0 < 1.1 do
            local a = math.min(1, (tick() - t0) / 0.35)
            line.To = line.From:Lerp(to, a)
            task.wait()
        end
        pcall(function() line:Remove() end)
    end)
    toast(kind == "knife" and "Предпросмотр ножа" or (kind == "gun" and "Предпросмотр пистолета" or "Предпросмотр трейсера"))
end
FEATURES["preview tracer"] = function() previewFx("tracer") end
FEATURES["preview knife tracer"] = function() previewFx("knife") end
FEATURES["preview gun kill"] = function() previewFx("gun") end
FEATURES["preview knife kill"] = function() previewFx("knife") end

