-- ==========================================================================
-- Komaru parity layer: generic wiring, chams, skeleton, settings, configs
-- ==========================================================================
do
    local function rowLabel(row)
                local lbl = findRowLabel(row)
        local label = norm(lbl and lbl.Text)
        if label == "" then
            local right = row:FindFirstChild("Right")
            local b = row:FindFirstChild("Button") or (right and right:FindFirstChild("Button", true))
            if b then
                for _, x in ipairs(b:GetDescendants()) do
                    if x:IsA("TextLabel") and norm(x.Text) ~= "" then label = norm(x.Text) break end
                end
            end
        end
        return label
    end
    local function gkey(label) return "g_" .. string.gsub(label, "[^%w]+", "_") end
    local wired = 0
    for _, tab in ipairs(BODY:GetChildren()) do
        if tab:IsA("CanvasGroup") then
            for _, row in ipairs(tab:GetDescendants()) do
                if row:IsA("Frame") and row.Name == "Row" then
                    local label = rowLabel(row)
                    if label ~= "" and not FEATURES[label] then
                        local right = row:FindFirstChild("Right")
                        local function inRight(name)
                            if not right then return nil end
                            return right:FindFirstChild(name) or right:FindFirstChild(name, true)
                        end
                        local sw = row:FindFirstChild("Switch") or inRight("Switch")
                        local track = row:FindFirstChild("Track") or inRight("Track")
                        local box = row:FindFirstChild("Box") or inRight("Box")
                        local button = row:FindFirstChild("Button") or inRight("Button")
                        local bind = row:FindFirstChild("Bind") or inRight("Bind")
                        local key = gkey(label)
                        if sw then
                            S[key] = false
                            FEATURES[label] = function(v) S[key] = v ~= false end
                            wired = wired + 1
                        elseif track then
                            S[key] = 0
                            FEATURES[label] = function(v) S[key] = v end
                            wired = wired + 1
                        elseif box then
                            S[key] = label
                            FEATURES[label] = function(v) S[key] = v end
                            wired = wired + 1
                        elseif button then
                            FEATURES[label] = function() end
                            wired = wired + 1
                        elseif bind then
                            S.binds = S.binds or {}
                            FEATURES[label] = function() end
                            wired = wired + 1
                        end
                    end
                end
            end
        end
    end
    _G.KomaruGenericWired = wired
end

-- Chams (Highlight) --------------------------------------------------------
do
    local cache = {}
    local function clear()
        for _, h in pairs(cache) do pcall(function() h:Destroy() end) end
        cache = {}
    end
    RunService.Heartbeat:Connect(function()
        if not alive() then return end
        if not S.chams then
            if next(cache) then clear() end
            return
        end
        local seen = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character then
                local role = getRole(p)
                local show = (role == "Murderer" and S.espShowMurderer ~= false)
                    or (role == "Sheriff" and S.espShowSheriff ~= false)
                    or (role == "Innocent" and S.espShowInnocent ~= false)
                if show and p.Character:FindFirstChild("HumanoidRootPart") then
                    seen[p] = true
                    local h = cache[p]
                    if not h or not h.Parent then
                        h = Instance.new("Highlight")
                        h.Name = "KomaruChams"
                        h.Parent = p.Character
                        cache[p] = h
                    end
                    local cc = S.espCfg or {}
                    local fillStrength = tonumber(cc.fillStrength) or 24
                    local style = cc.chamsStyle or "Outline"
                    local roleCol = ROLE_COLORS[role] or ROLE_COLORS.Innocent
                    h.Adornee = p.Character
                    h.DepthMode = (S.throughWalls or cc.throughWalls) and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded
                    h.FillColor = (cc.roleColors == false) and Color3.new(1, 1, 1) or roleCol
                    h.FillTransparency = style == "Outline" and 0.92 or math.clamp(1 - fillStrength / 100 * 1.4, 0.05, 0.95)
                    h.OutlineColor = cc.roleEdge and roleCol or Color3.new(1, 1, 1)
                    h.OutlineTransparency = (style == "Fill" or cc.chamsOutline == false) and 1 or 0.35
                end
            end
        end
        for p, h in pairs(cache) do
            if not seen[p] then pcall(function() h:Destroy() end) cache[p] = nil end
        end
    end)
end

-- Skeleton + health bars ---------------------------------------------------
do
    local cache = {}
    local acc = 0
    local function clearEntry(e)
        for _, l in ipairs(e.bones or {}) do pcall(function() l:Remove() end) end
        if e.hbg then pcall(function() e.hbg:Remove() end) end
        if e.hfill then pcall(function() e.hfill:Remove() end) end
    end
    local function clearAll() for p, e in pairs(cache) do clearEntry(e) cache[p] = nil end end
    local function newDraw2(kind)
        local ok, o = pcall(function() return Drawing.new(kind) end)
        return ok and o or nil
    end
    RunService.RenderStepped:Connect(function(dt)
        if not alive() then return end
        if not (S.skeleton or S.espHealth) then
            if next(cache) then clearAll() end
            return
        end
        acc = acc + dt
        if acc < 0.05 then return end
        acc = 0
        local cam = workspace.CurrentCamera
        if not cam then return end
        local seen = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character then
                local char = p.Character
                local root = char:FindFirstChild("HumanoidRootPart")
                local head = char:FindFirstChild("Head")
                local hum = char:FindFirstChildOfClass("Humanoid")
                if root and head and hum and hum.Health > 0 then
                    local role = getRole(p)
                    local show = (role == "Murderer" and S.espShowMurderer ~= false)
                        or (role == "Sheriff" and S.espShowSheriff ~= false)
                        or (role == "Innocent" and S.espShowInnocent ~= false)
                    local dist = (root.Position - cam.CFrame.Position).Magnitude
                    if show and (not S.maxDist or S.maxDist <= 0 or dist <= S.maxDist) then
                        seen[p] = true
                        local e = cache[p]
                        if not e then e = { bones = {} } cache[p] = e end
                        local color = ROLE_COLORS[role] or ROLE_COLORS.Innocent
                        if S.espHealth then
                            local top = head.Position + Vector3.new(0, 1.2, 0)
                            local bottom = root.Position - Vector3.new(0, 3, 0)
                            local tv, tOn = cam:WorldToViewportPoint(top)
                            local bv, bOn = cam:WorldToViewportPoint(bottom)
                            if tOn and bOn then
                                local h = math.abs(bv.Y - tv.Y)
                                local w = h * 0.55
                                local x = tv.X - w / 2 - 6
                                if not e.hbg then e.hbg = newDraw2("Square") end
                                if not e.hfill then e.hfill = newDraw2("Square") end
                                if e.hbg and e.hfill then
                                    local frac = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
                                    e.hbg.Visible = true
                                    e.hbg.Size = Vector2.new(3, h)
                                    e.hbg.Position = Vector2.new(x, tv.Y)
                                    e.hbg.Color = Color3.fromRGB(20, 20, 20)
                                    e.hbg.Thickness = 1
                                    e.hbg.Filled = true
                                    e.hbg.Transparency = 0.25
                                    e.hfill.Visible = true
                                    e.hfill.Size = Vector2.new(3, h * frac)
                                    e.hfill.Position = Vector2.new(x, tv.Y + h * (1 - frac))
                                    e.hfill.Color = Color3.fromRGB(90, 220, 120)
                                    e.hfill.Thickness = 1
                                    e.hfill.Filled = true
                                    e.hfill.Transparency = 0.1
                                end
                            else
                                if e.hbg then e.hbg.Visible = false end
                                if e.hfill then e.hfill.Visible = false end
                            end
                        else
                            if e.hbg then e.hbg.Visible = false end
                            if e.hfill then e.hfill.Visible = false end
                        end
                        if S.skeleton then
                            local idx = 0
                            for _, m in ipairs(char:GetDescendants()) do
                                if m:IsA("Motor6D") and m.Part0 and m.Part1 then
                                    idx = idx + 1
                                    if idx > 40 then break end
                                    local line = e.bones[idx]
                                    if not line then line = newDraw2("Line") e.bones[idx] = line end
                                    if line then
                                        local a = cam:WorldToViewportPoint(m.Part0.Position)
                                        local b = cam:WorldToViewportPoint(m.Part1.Position)
                                        if a.Z > 0 and b.Z > 0 then
                                            line.Visible = true
                                            line.From = Vector2.new(a.X, a.Y)
                                            line.To = Vector2.new(b.X, b.Y)
                                            line.Color = color
                                            line.Thickness = math.clamp(tonumber(S.espCfg and S.espCfg.boneThickness) or 1, 0.5, 8)
                                            line.Transparency = 1 - math.clamp(tonumber(S.espCfg and S.espCfg.boneOpacity) or 85, 0, 100) / 100
                                        else
                                            line.Visible = false
                                        end
                                    end
                                end
                            end
                            for i = idx + 1, #e.bones do pcall(function() e.bones[i].Visible = false end) end
                        else
                            for _, l in ipairs(e.bones) do pcall(function() l.Visible = false end) end
                        end
                    end
                end
            end
        end
        for p, e in pairs(cache) do
            if not seen[p] then clearEntry(e) cache[p] = nil end
        end
    end)
    Players.PlayerRemoving:Connect(function(p)
        local e = cache[p]
        if e then clearEntry(e) cache[p] = nil end
    end)
end

-- Settings effects ---------------------------------------------------------
do
    local function win() return ROOT and ROOT:FindFirstChild("Window") end
    FEATURES["background intensity"] = function(v)
        local w = win()
        local bd = w and w:FindFirstChild("Backdrop")
        if bd then bd.BackgroundTransparency = math.clamp(1 - (tonumber(v) or 100) / 100, 0, 1) end
    end
    FEATURES["corner radius"] = function(v)
        local w = win()
        if w then
            local uc = w:FindFirstChildOfClass("UICorner")
            if not uc then uc = Instance.new("UICorner") uc.Parent = w end
            uc.CornerRadius = UDim.new(0, math.clamp(tonumber(v) or 12, 0, 32))
        end
    end
    FEATURES["sidebar width"] = function(v)
        if SIDEBAR then SIDEBAR.Size = UDim2.new(0, math.clamp(tonumber(v) or 232, 160, 320), 1, 0) end
    end
    local textBase = setmetatable({}, { __mode = "k" })
    local function applyTextScale(mult)
        mult = math.clamp(tonumber(mult) or 1, 0.7, 1.4)
        for _, d in ipairs(ROOT:GetDescendants()) do
            if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then
                if not textBase[d] then textBase[d] = d.TextSize end
                d.TextSize = math.clamp(math.floor(textBase[d] * mult + 0.5), 8, 40)
            end
        end
    end
    FEATURES["text size"] = function(v) applyTextScale((tonumber(v) or 100) / 100) end
    FEATURES["screen stretch"] = function(v)
        local s = ROOT:FindFirstChildOfClass("UIScale")
        if s then s.Scale = 1 + (tonumber(v) or 0) / 200 end
    end
    FEATURES["launcher button"] = function(v)
        local l = GUI:FindFirstChild("Launcher", true)
        if l and l:IsA("GuiObject") then l.Visible = v ~= false end
    end
    FEATURES["no map lights"] = function(v)
        for _, d in ipairs(workspace:GetDescendants()) do
            if d:IsA("Light") then pcall(function() d.Enabled = not v end) end
        end
    end
    FEATURES["no post effects"] = function(v)
        for _, e in ipairs(Lighting:GetChildren()) do
            if e:IsA("BlurEffect") or e:IsA("BloomEffect") or e:IsA("SunRaysEffect")
                or e:IsA("DepthOfFieldEffect") or e:IsA("ColorCorrectionEffect") then
                pcall(function() e.Enabled = not v end)
            end
        end
    end
    FEATURES["plastic materials"] = function(v)
        if v then
            for _, d in ipairs(workspace:GetDescendants()) do
                if d:IsA("BasePart") then pcall(function() d.Material = Enum.Material.Plastic end) end
            end
