    end
    local blur
    FEATURES["blur behind menu"] = function(v)
        if v then
            if not blur then
                blur = Instance.new("BlurEffect")
                blur.Size = 12
                blur.Parent = Lighting
            end
        elseif blur then
            pcall(function() blur:Destroy() end)
