    FEATURES["animations"] = function(v) _G.KomaruAnimations = v ~= false end
    FEATURES["anti-glare"] = function(v)
        pcall(function() Lighting.EnvironmentDiffuseScale = v and 0.5 or 1 end)
        pcall(function() Lighting.EnvironmentSpecularScale = v and 0.5 or 1 end)
    end
    FEATURES["compact sidebar"] = function(v)
        if SIDEBAR then SIDEBAR.Size = UDim2.new(0, v and 176 or 232, 1, 0) end
    end
    FEATURES["fit to screen"] = function()
        local cam = workspace.CurrentCamera
        local s = ROOT:FindFirstChildOfClass("UIScale")
        if cam and s then
