        toast("Все кнопки доступны")
    end
end

-- Configs ------------------------------------------------------------------
do
    local path = "KomaruHub_config.json"
    local function saveCfg()
        local data = {}
        for k, v in pairs(S) do
            local t = type(v)
            if t == "number" or t == "string" or t == "boolean" then data[k] = v end
        end
        if type(S.colors) == "table" then
            local cs = {}
            for name, col in pairs(S.colors) do
                if typeof(col) == "Color3" then
                    cs[name] = string.format("%d,%d,%d",
                        math.floor(col.R * 255 + 0.5), math.floor(col.G * 255 + 0.5), math.floor(col.B * 255 + 0.5))
                end
            end
            data.__colors = cs
        end
        local tg = {}
        for label, get in pairs(TOGGLE_STATE) do
            local ok, st = pcall(get)
            if ok then tg[label] = st and true or false end
        end
        data.__toggles = tg
        local ok = pcall(function() writefile(path, HttpService:JSONEncode(data)) end)
        toast(ok and "Конфиг сохранён" or "Не удалось сохранить конфиг")
    end
    local function loadCfg()
        if type(isfile) ~= "function" or not isfile(path) then toast("Конфиг не найден") return end
        local ok, data = pcall(function() return HttpService:JSONDecode(readfile(path)) end)
        if not ok or type(data) ~= "table" then toast("Ошибка чтения конфига") return end
        local cs = data.__colors
        local tg = data.__toggles
        data.__colors = nil
        data.__toggles = nil
        for k, v in pairs(data) do S[k] = v end
        for label, f in pairs(TOGGLE_SYNC) do
            local want = (type(tg) == "table" and tg[label] == true) or (type(tg) ~= "table" and S[gkey(label)] == true)
            pcall(f, want)
        end
        if type(cs) == "table" then
            S.colors = S.colors or {}
            for name, s in pairs(cs) do
                local r, g, b = string.match(tostring(s), "(%d+),(%d+),(%d+)")
                if r then
                    local col = Color3.fromRGB(tonumber(r), tonumber(g), tonumber(b))
                    S.colors[name] = col
                    local fn = FEATURES[name]
                    if fn then pcall(fn, col) end
                end
            end
        end
        toast("Конфиг загружен")
    end
    FEATURES["save current"] = saveCfg
    FEATURES["create config"] = saveCfg
    FEATURES["import config"] = loadCfg
    FEATURES["delete"] = function()
        pcall(function()
            local df = rawget(getfenv(0), "delfile") or rawget(getfenv(0), "deletefile")
            if df and type(isfile) == "function" and isfile(path) then df(path) end
        end)
        toast("Конфиг удалён")
    end
    FEATURES["publish"] = function() toast("Публикация недоступна") end
    FEATURES["apply"] = function() toast("Настройки применены") end
end

