-- Anti-fling hard guard ----------------------------------------------------
RunService.Heartbeat:Connect(function()
    if not alive() or not S.antiFling then return end
    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return end
    if root.AssemblyLinearVelocity.Magnitude > 400 then
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end
    for _, d in ipairs(root:GetChildren()) do
        if d:IsA("WeldConstraint") or d:IsA("Weld") or d:IsA("ManualWeld") then
            local other = (d.Part0 == root and d.Part1) or (d.Part1 == root and d.Part0)
            if other and not other:IsDescendantOf(char) then pcall(function() d:Destroy() end) end
        end
    end
end)

-- FPS / ping overlay --------------------------------------------------------
do
    local gui, txt, frames, acc = nil, nil, 0, 0
    RunService.RenderStepped:Connect(function(dt)
        if not alive() then return end
        if not S.showFps then
            if gui then gui.Enabled = false end
            return
        end
        if not gui or not gui.Parent then
            gui = Instance.new("ScreenGui")
            gui.Name = "KomaruFPS"
            gui.ResetOnSpawn = false
            gui.IgnoreGuiInset = true
            gui.DisplayOrder = 2147483000
            gui.Parent = GUI.Parent
            txt = Instance.new("TextLabel")
            txt.BackgroundTransparency = 1
            txt.Font = Enum.Font.GothamMedium
            txt.TextSize = 13
            txt.TextColor3 = Color3.fromRGB(235, 235, 238)
            txt.TextXAlignment = Enum.TextXAlignment.Right
            txt.Size = UDim2.new(0, 170, 0, 20)
            txt.Position = UDim2.new(1, -12, 0, 8)
            txt.AnchorPoint = Vector2.new(1, 0)
            txt.Parent = gui
        end
        gui.Enabled = true
        frames = frames + 1
        acc = acc + dt
        if acc >= 0.5 then
            local fps = math.floor(frames / acc + 0.5)
            local ping = 0
            pcall(function() ping = math.floor(LP:GetNetworkPing() * 1000 + 0.5) end)
            txt.Text = string.format("FPS %d   PING %d", fps, ping)
            frames, acc = 0, 0
        end
    end)
end
-- Players list panel --------------------------------------------------------
do
    local panelGui, panel, list, listLayout, titleLbl

    local function makeRow()
        local row = Instance.new("Frame")
        row.Size = UDim2.new(1, -6, 0, 30)
        row.BackgroundColor3 = Color3.fromRGB(30, 27, 40)
        row.BorderSizePixel = 0
        local rc = Instance.new("UICorner")
        rc.CornerRadius = UDim.new(0, 7)
        rc.Parent = row

        local name = Instance.new("TextLabel")
        name.BackgroundTransparency = 1
        name.Position = UDim2.new(0, 8, 0, 0)
        name.Size = UDim2.new(1, -70, 1, 0)
        name.Font = Enum.Font.GothamMedium
        name.TextSize = 13
        name.TextXAlignment = Enum.TextXAlignment.Left
        name.TextTruncate = Enum.TextTruncate.AtEnd
        name.TextColor3 = Color3.fromRGB(235, 235, 238)
        name.Parent = row

        local tp = Instance.new("TextButton")
        tp.Size = UDim2.new(0, 52, 0, 22)
        tp.Position = UDim2.new(1, -60, 0.5, -11)
        tp.BackgroundColor3 = Color3.fromRGB(124, 92, 255)
        tp.BorderSizePixel = 0
        tp.Font = Enum.Font.GothamBold
        tp.TextSize = 12
        tp.TextColor3 = Color3.fromRGB(255, 255, 255)
        tp.Text = "TP"
        tp.Parent = row
        local tc = Instance.new("UICorner")
        tc.CornerRadius = UDim.new(0, 6)
        tc.Parent = tp

        return row, name, tp
    end

    local function tpTo(plr)
        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local tchar = plr and plr.Character
        local troot = tchar and tchar:FindFirstChild("HumanoidRootPart")
        if root and troot then
            root.CFrame = troot.CFrame * CFrame.new(0, 0, 2.5)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
    end

    local rowPool = {}

    local function rowFor(i)
        if rowPool[i] then return rowPool[i] end
        local row, lbl, btn = makeRow()
        btn.MouseButton1Click:Connect(function()
            if row.player then tpTo(row.player) end
        end)
        row.nameLbl = lbl
        row.LayoutOrder = i
        row.Parent = list
        rowPool[i] = row
        return row
    end

    local function refresh()
        if not panel or not panel.Visible then return end
        local plrs = Players:GetPlayers()
        table.sort(plrs, function(a, b) return a.Name:lower() < b.Name:lower() end)
        titleLbl.Text = string.format("PLAYERS  ·  %d", #plrs)
        for i, plr in ipairs(plrs) do
            local row = rowFor(i)
            row.Visible = true
            row.LayoutOrder = i
            row.player = plr
            local label = plr.Name
            if plr.DisplayName and plr.DisplayName ~= plr.Name then
                label = plr.DisplayName .. "  @" .. plr.Name
            end
            if plr == LP then label = label .. "  (you)" end
            row.nameLbl.Text = label
            row.nameLbl.TextColor3 = (plr == LP) and Color3.fromRGB(124, 92, 255) or Color3.fromRGB(235, 235, 238)
        end
        for i = #plrs + 1, #rowPool do rowPool[i].Visible = false end
        list.CanvasSize = UDim2.new(0, 0, 0, listLayout.AbsoluteContentSize.Y + 8)
    end

    local function build()
        panelGui = Instance.new("ScreenGui")
        panelGui.Name = "KomaruPlayers"
        panelGui.ResetOnSpawn = false
        panelGui.IgnoreGuiInset = true
        panelGui.DisplayOrder = 2147483000
        panelGui.Parent = GUI.Parent

        local toggle = Instance.new("TextButton")
        toggle.Size = UDim2.new(0, 112, 0, 34)
        toggle.Position = UDim2.new(1, -128, 1, -150)
        toggle.BackgroundColor3 = Color3.fromRGB(22, 20, 30)
        toggle.TextColor3 = Color3.fromRGB(235, 235, 238)
        toggle.Font = Enum.Font.GothamBold
        toggle.TextSize = 13
        toggle.Text = "👥 PLAYERS"
        toggle.BorderSizePixel = 0
        toggle.Parent = panelGui
        local tcg = Instance.new("UICorner")
        tcg.CornerRadius = UDim.new(0, 10)
        tcg.Parent = toggle
        local tst = Instance.new("UIStroke")
        tst.Color = Color3.fromRGB(124, 92, 255)
        tst.Thickness = 1.5
        tst.Parent = toggle

        panel = Instance.new("Frame")
        panel.Size = UDim2.new(0, 252, 0, 340)
        panel.Position = UDim2.new(1, -268, 0.5, -170)
        panel.BackgroundColor3 = Color3.fromRGB(18, 16, 24)
        panel.BorderSizePixel = 0
        panel.Visible = false
        panel.Parent = panelGui
        local pcg = Instance.new("UICorner")
        pcg.CornerRadius = UDim.new(0, 12)
        pcg.Parent = panel
        local pst = Instance.new("UIStroke")
        pst.Color = Color3.fromRGB(124, 92, 255)
        pst.Thickness = 1.5
        pst.Parent = panel

        local head = Instance.new("Frame")
        head.Size = UDim2.new(1, 0, 0, 38)
        head.BackgroundTransparency = 1
        head.Parent = panel

        titleLbl = Instance.new("TextLabel")
        titleLbl.BackgroundTransparency = 1
        titleLbl.Position = UDim2.new(0, 12, 0, 0)
        titleLbl.Size = UDim2.new(1, -48, 1, 0)
        titleLbl.Font = Enum.Font.GothamBold
        titleLbl.TextSize = 14
        titleLbl.TextXAlignment = Enum.TextXAlignment.Left
        titleLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        titleLbl.Text = "PLAYERS"
        titleLbl.Parent = head

        local close = Instance.new("TextButton")
        close.Size = UDim2.new(0, 24, 0, 24)
        close.Position = UDim2.new(1, -34, 0.5, -12)
        close.BackgroundColor3 = Color3.fromRGB(38, 34, 50)
        close.TextColor3 = Color3.fromRGB(200, 195, 210)
        close.Font = Enum.Font.GothamBold
        close.TextSize = 14
        close.Text = "✕"
        close.BorderSizePixel = 0
        close.Parent = head
        local ccg = Instance.new("UICorner")
        ccg.CornerRadius = UDim.new(0, 6)
        ccg.Parent = close

        list = Instance.new("ScrollingFrame")
        list.Position = UDim2.new(0, 8, 0, 42)
        list.Size = UDim2.new(1, -16, 1, -50)
        list.BackgroundTransparency = 1
        list.BorderSizePixel = 0
        list.ScrollBarThickness = 4
        list.CanvasSize = UDim2.new(0, 0, 0, 0)
        list.Parent = panel
        listLayout = Instance.new("UIListLayout")
        listLayout.Padding = UDim.new(0, 6)
        listLayout.SortOrder = Enum.SortOrder.LayoutOrder
        listLayout.Parent = list

        toggle.MouseButton1Click:Connect(function()
            panel.Visible = not panel.Visible
            refresh()
        end)
        close.MouseButton1Click:Connect(function() panel.Visible = false end)

        local dragging, dragStart, startPos = false, nil, nil
        head.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                dragStart = input.Position
                startPos = panel.Position
            end
        end)
        UIS.InputChanged:Connect(function(input)
            if not dragging then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement
                and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local d = input.Position - dragStart
            panel.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X,
                                       startPos.Y.Scale, startPos.Y.Offset + d.Y)
        end)
        UIS.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                dragging = false
            end
        end)
    end

    build()
    task.spawn(function()
        while task.wait(1) do
            if panel and panel.Visible then refresh() end
        end
    end)
    Players.PlayerAdded:Connect(function() task.wait(0.3) refresh() end)
    Players.PlayerRemoving:Connect(function() task.wait(0.1) refresh() end)

    FEATURES["player list"] = function(v)
        panel.Visible = (v == nil) and (not panel.Visible) or (v and true or false)
        refresh()
    end
    FEATURES["players list"] = FEATURES["player list"]
end
