-- Keybinds ----------------------------------------------------------------
do
    if type(S.binds) ~= "table" then S.binds = {} end
    if type(S.bindOn) ~= "table" then S.bindOn = {} end
    S.binds["menu key"] = S.binds["menu key"] or "RightShift"
    FEATURES["menu key"] = function()
        if ROOT then ROOT.Visible = not ROOT.Visible end
    end
    UIS.InputBegan:Connect(function(input, gpe)
        if gpe or not alive() then return end
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        local name = input.KeyCode.Name
        for label, kc in pairs(S.binds) do
            if kc == name then
                local fn = FEATURES[label]
                if fn then
                    local on = not S.bindOn[label]
                    S.bindOn[label] = on
                    pcall(fn, on)
                end
            end
        end
    end)
    for _, row in ipairs(BODY:GetDescendants()) do
        if row:IsA("Frame") and row.Name == "Row" then
            local right = row:FindFirstChild("Right")
            local bind = right and right:FindFirstChild("Bind", true)
            if bind then
        local lbl = findRowLabel(row)
                local label = norm(lbl and lbl.Text)
                if label ~= "" and S.binds[label] then
                    for _, d in ipairs(bind:GetDescendants()) do
                        if d:IsA("TextLabel") then d.Text = S.binds[label] break end
                    end
                end
            end
        end
    end
end

-- UI font / language -------------------------------------------------------
FEATURES["font"] = function(v)
    if type(v) ~= "string" then return end
    local map = {
        gotham = Enum.Font.GothamBold,
        gothambold = Enum.Font.GothamBold,
        gothammedium = Enum.Font.GothamBold,
        sourcesans = Enum.Font.SourceSansBold,
        sourcesansbold = Enum.Font.SourceSansBold,
        code = Enum.Font.Code,
    }
    local f = map[string.lower(v)]
    if not f then return end
    S.fontChoice = v
    for _, d in ipairs(GUI:GetDescendants()) do
        if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then
            pcall(function() d.Font = f end)
        end
    end
end
FEATURES["language"] = function(v)
    if type(v) ~= "string" then return end
    S.langChoice = v
    toast(v == "Russian" and "Язык: русский" or "Language: English")
end

--------------------------------------------------------------------------
-- pulse-parity: environment visuals (lighting / air / sky / fx / weather)
--------------------------------------------------------------------------
do
    local vis = S.vis or {}
    S.vis = vis

    local function hex(str, def)
        if type(str) ~= "string" then return def or Color3.new(1, 1, 1) end
        str = str:gsub("#", "")
        if #str < 6 then return def or Color3.new(1, 1, 1) end
        return Color3.fromRGB(tonumber(str:sub(1, 2), 16) or 255, tonumber(str:sub(3, 4), 16) or 255, tonumber(str:sub(5, 6), 16) or 255)
    end

    local base = {}
    local function capture()
        if base.done then return end
        base.done = true
        for _, p in ipairs({ "Brightness", "Ambient", "OutdoorAmbient", "ColorShift_Top", "ColorShift_Bottom", "GlobalShadows", "EnvironmentDiffuseScale", "EnvironmentSpecularScale", "ExposureCompensation", "GeographicLatitude", "ShadowSoftness", "ClockTime", "FogStart", "FogEnd", "FogColor" }) do
            base[p] = Lighting[p]
        end
    end

    local function fxFolder()
        local f = Lighting:FindFirstChild("KomaruFX")
        if not f then
            f = Instance.new("Folder")
            f.Name = "KomaruFX"
            f.Parent = Lighting
        end
        return f
    end

    local function ensure(class, name)
        local f = fxFolder()
        local c = f:FindFirstChild(name)
        if not c or c.ClassName ~= class then
            if c then c:Destroy() end
            c = Instance.new(class)
            c.Name = name
            c.Parent = f
        end
        return c
    end

    local function drop(name)
        local f = Lighting:FindFirstChild("KomaruFX")
        local c = f and f:FindFirstChild(name)
        if c then c:Destroy() end
    end

    local function applyLighting()
        capture()
        Lighting.Brightness = vis.brightnessOn and (vis.lightLevel or 2) or base.Brightness
        Lighting.GlobalShadows = vis.noShadows and false or base.GlobalShadows
        Lighting.ClockTime = vis.hourSet and (vis.hour or 14) or base.ClockTime
        Lighting.GeographicLatitude = vis.latSet and (vis.latitude or 41.7) or base.GeographicLatitude
        Lighting.ShadowSoftness = vis.softSet and (vis.softness or 0.5) or base.ShadowSoftness
        Lighting.ExposureCompensation = vis.exposureOn and ((vis.exposure or 0) / 10) or base.ExposureCompensation
        if vis.envOn then
            local s = math.clamp((vis.reflections or 1) * 0.5, 0, 1)
            Lighting.EnvironmentDiffuseScale = s
            Lighting.EnvironmentSpecularScale = s
        else
            Lighting.EnvironmentDiffuseScale = base.EnvironmentDiffuseScale
            Lighting.EnvironmentSpecularScale = base.EnvironmentSpecularScale
        end
        if vis.lightColors then
            Lighting.Ambient = hex(vis.indoor, Color3.fromRGB(150, 150, 150))
            Lighting.OutdoorAmbient = hex(vis.outdoor, Color3.fromRGB(170, 170, 170))
            Lighting.ColorShift_Top = hex(vis.sunlit, Color3.new(0, 0, 0))
            Lighting.ColorShift_Bottom = hex(vis.shaded, Color3.new(0, 0, 0))
        else
            Lighting.Ambient = base.Ambient
            Lighting.OutdoorAmbient = base.OutdoorAmbient
            Lighting.ColorShift_Top = base.ColorShift_Top
            Lighting.ColorShift_Bottom = base.ColorShift_Bottom
        end
        if vis.ambientOn then
            local t = hex(vis.ambientTint, Color3.new(1, 1, 1))
            local m = math.clamp(vis.ambientLevel or 1, 0, 2)
            Lighting.Ambient = Color3.new(t.R * m, t.G * m, t.B * m)
            Lighting.OutdoorAmbient = Color3.new(t.R * m, t.G * m, t.B * m)
        end
    end

    local function applyAir()
        if vis.airOn then
            local a = ensure("Atmosphere", "KomaruAtmo")
            a.Density = math.clamp(vis.airDensity or 0.28, 0, 1)
            a.Color = hex(vis.airColor, Color3.fromRGB(199, 211, 230))
            a.Decay = hex(vis.airColor2, Color3.fromRGB(190, 190, 190))
            a.Glare = math.clamp(vis.sunGlare or 0.1, 0, 10)
            a.Haze = math.clamp(vis.haze or 1, 0, 10)
            a.Offset = math.clamp(vis.horizonOffset or 0.1, -1, 1)
        else
            drop("KomaruAtmo")
        end
        if vis.noAtmo then
            for _, c in ipairs(Lighting:GetChildren()) do
                if c:IsA("Atmosphere") then c:Destroy() end
            end
        end
        if vis.fogOn then
            Lighting.FogStart = vis.fogStart or 0
            Lighting.FogEnd = math.max(vis.fogEnd or 2000, (vis.fogStart or 0) + 1)
        else
            Lighting.FogStart = base.FogStart
            Lighting.FogEnd = base.FogEnd
        end
    end

    local function applySky()
        if vis.skyDirty then
            local sky = ensure("Sky", "KomaruSky")
            sky.SkyboxBk = "rbxasset://textures/sky/sky512_bk.tex"
            sky.SkyboxDn = "rbxasset://textures/sky/sky512_dn.tex"
            sky.SkyboxFt = "rbxasset://textures/sky/sky512_ft.tex"
            sky.SkyboxLf = "rbxasset://textures/sky/sky512_lf.tex"
            sky.SkyboxRt = "rbxasset://textures/sky/sky512_rt.tex"
            sky.SkyboxUp = "rbxasset://textures/sky/sky512_up.tex"
            sky.CelestialBodiesShown = vis.sunMoon ~= false
            sky.StarCount = math.clamp(math.floor(vis.starCount or 3000), 0, 5000)
            if vis.sunSize then sky.SunAngularSize = math.clamp(math.floor(vis.sunSize), 0, 60) end
            if vis.moonSize then sky.MoonAngularSize = math.clamp(math.floor(vis.moonSize), 0, 60) end
        else
            drop("KomaruSky")
        end
    end

    local function applyCC()
        if vis.ccOn then
            local cc = ensure("ColorCorrectionEffect", "KomaruCC")
            cc.Brightness = (vis.ccBrightness or 0) / 100
            cc.Contrast = (vis.ccContrast or 0) / 100
            cc.Saturation = 1 + (vis.ccSaturation or 0) / 100
            cc.TintColor = hex(vis.ccTint, Color3.new(1, 1, 1))
            local styles = {
                cinematic = { -0.03, 0.12, 0.05 },
                warm = { 0.04, 0.05, 0.1 },
                cold = { -0.02, 0.08, -0.1 },
                noir = { -0.05, 0.2, -1 },
                vivid = { 0.02, 0.15, 0.35 },
            }
            local st = styles[string.lower(tostring(vis.ccStyle or ""))]
            if st then
                cc.Brightness = cc.Brightness + st[1]
                cc.Contrast = cc.Contrast + st[2]
                cc.Saturation = cc.Saturation + st[3]
            end
        else
            drop("KomaruCC")
        end
    end

    local function applyGlow()
        if vis.bloom then
            local b = ensure("BloomEffect", "KomaruBloom")
            b.Intensity = math.clamp(vis.glowIntensity or 0.3, 0, 5)
            b.Size = math.clamp(vis.glowRadius or 24, 0, 64)
            b.Threshold = math.clamp(vis.glowThreshold or 1.2, 0, 5)
        else
            drop("KomaruBloom")
        end
        if vis.sunRays then
            local s = ensure("SunRaysEffect", "KomaruRays")
            s.Intensity = math.clamp(vis.rayIntensity or 0.06, 0, 1)
            s.Spread = math.clamp(vis.raySpread or 0.8, 0, 1)
        else
            drop("KomaruRays")
        end
    end

    local vignette
    local function ensureVignette()
        if vignette then return vignette end
        vignette = Instance.new("Frame")
        vignette.Name = "KomaruVignette"
        vignette.BackgroundTransparency = 1
        vignette.BorderSizePixel = 0
        vignette.Size = UDim2.fromScale(1, 1)
        vignette.ZIndex = 0
        vignette.Visible = false
        vignette.Parent = GUI
        for _, cfg in ipairs({
            { "Top", Vector2.new(0.5, 0), UDim2.fromScale(0.5, 0), UDim2.fromScale(1, 0.32), 90 },
            { "Bottom", Vector2.new(0.5, 1), UDim2.fromScale(0.5, 1), UDim2.fromScale(1, 0.32), 270 },
            { "Left", Vector2.new(0, 0.5), UDim2.fromScale(0, 0.5), UDim2.fromScale(0.28, 1), 0 },
            { "Right", Vector2.new(1, 0.5), UDim2.fromScale(1, 0.5), UDim2.fromScale(0.28, 1), 180 },
        }) do
            local f = Instance.new("Frame")
            f.Name = "V_" .. cfg[1]
            f.AnchorPoint = cfg[2]
            f.Position = cfg[3]
            f.Size = cfg[4]
            f.BorderSizePixel = 0
            f.BackgroundColor3 = Color3.new(0, 0, 0)
            f.Parent = vignette
            local g = Instance.new("UIGradient")
            g.Rotation = cfg[5]
            g.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) })
            g.Parent = f
        end
        return vignette
    end

    local function applyScreen()
        if vis.blurOn then
            local b = ensure("BlurEffect", "KomaruBlur")
            b.Size = math.clamp((vis.blurStrength or 0.14) * 40, 0, 56)
        else
            drop("KomaruBlur")
        end
        if vis.dofOn then
            local d = ensure("DepthOfFieldEffect", "KomaruDOF")
            d.FocusDistance = math.clamp(vis.focusDistance or 50, 0, 500)
            d.InFocusRadius = math.clamp(vis.sharpZone or 60, 1, 500)
            d.FarIntensity = 0.6
        else
            drop("KomaruDOF")
        end
        local v = ensureVignette()
        v.Visible = vis.vignette and true or false
        local strength = math.clamp(1 - (vis.edgeShade or 35) / 100, 0.05, 0.95)
        for _, f in ipairs(v:GetChildren()) do
            local g = f:FindFirstChildOfClass("UIGradient")
            if g then
                g.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, strength), NumberSequenceKeypoint.new(1, 1) })
            end
        end
    end

    local wFold, wPart, wEmit, wConn
    local kinds = {
        snow = { key = "snowColour", speed = 12, accel = Vector3.new(0, -2.5, 0), size = 1.2, life = 7 },
        rain = { key = "mistColour", speed = 60, accel = Vector3.new(0, -35, 0), size = 0.45, life = 1.6 },
        blossom = { key = "petalColour", speed = 8, accel = Vector3.new(0, -2, 0), size = 0.8, life = 7 },
        leaves = { key = "leafColour", speed = 7, accel = Vector3.new(0, -2, 0), size = 0.7, life = 7 },
        fireflies = { key = "fireflyColour", speed = 2, accel = Vector3.new(0, 0.4, 0), size = 1, life = 9, glow = 1 },
        mist = { key = "mistColour", speed = 3, accel = Vector3.new(0, 0.1, 0), size = 4, life = 10 },
        embers = { key = "emberColour", speed = 5, accel = Vector3.new(0, 3, 0), size = 0.5, life = 5, glow = 1 },
        ash = { key = "ashColour", speed = 5, accel = Vector3.new(0, -1.5, 0), size = 0.7, life = 8 },
        pollen = { key = "pollenColour", speed = 3, accel = Vector3.new(0, 0.2, 0), size = 0.6, life = 8 },
    }

    local function weatherName()
        local k = string.lower(tostring(vis.weatherKind or "Snow"))
        if k == "blossom" or k == "snow" or k == "leaves" or k == "fireflies" or k == "mist" or k == "embers" or k == "ash" or k == "pollen" then
            return k
        end
        return "snow"
    end

    local function stopWeather()
        if wConn then wConn:Disconnect() wConn = nil end
        if wFold then wFold:Destroy() end
        wFold, wPart, wEmit = nil, nil, nil
    end

    local function weatherApply()
        if not vis.weatherOn then stopWeather() return end
        local k = weatherName()
        local cfg = kinds[k]
        if not wFold or not wEmit then
            stopWeather()
            wFold = Instance.new("Folder")
            wFold.Name = "KomaruWeather"
            wFold.Parent = workspace
            wPart = Instance.new("Part")
            wPart.Name = "KomaruWeatherEmitter"
            wPart.Size = Vector3.new(1, 1, 1)
            wPart.Anchored = true
            wPart.CanCollide = false
            wPart.CanQuery = false
            wPart.CanTouch = false
            wPart.Transparency = 1
            wPart.Parent = wFold
            wEmit = Instance.new("ParticleEmitter")
            wEmit.Name = "KomaruWeather"
            wEmit.Parent = wPart
            wConn = RunService.RenderStepped:Connect(function()
                if not wPart then return end
                local cam = workspace.CurrentCamera
                if cam then wPart.CFrame = cam.CFrame * CFrame.new(0, 26, 0) end
            end)
        end
        local amount = math.clamp(vis.weatherAmount or 60, 0, 100)
        local visib = math.clamp(vis.weatherVisibility or 80, 0, 100)
        local size = math.clamp(vis.weatherSize or 1, 0.1, 5)
        local wind = math.clamp(vis.windStrength or 5, 0, 40)
        local ang = math.rad(vis.windAngle or 35)
        local col = hex(vis.weatherCol and vis.weatherCol[cfg.key], Color3.new(1, 1, 1))
        wEmit.Color = ColorSequence.new(col)
        wEmit.Rate = amount * 1.4
        wEmit.Speed = NumberRange.new(cfg.speed * 0.6, cfg.speed * 1.4)
        wEmit.Lifetime = NumberRange.new(cfg.life * 0.7, cfg.life * 1.2)
        wEmit.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, cfg.size * size), NumberSequenceKeypoint.new(1, cfg.size * size * 0.55) })
        wEmit.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1 - visib / 100), NumberSequenceKeypoint.new(1, 1) })
        wEmit.Rotation = NumberRange.new(0, 360)
        wEmit.RotSpeed = NumberRange.new(-45, 45)
        wEmit.SpreadAngle = Vector2.new(35, 35)
        wEmit.LightEmission = cfg.glow or 0
        wEmit.LightInfluence = 0
        wEmit.Acceleration = cfg.accel + Vector3.new(math.sin(ang) * wind, 0, math.cos(ang) * wind)
        wEmit.Enabled = true
    end

    local lampStore = {}
    local function applyLamps()
        if vis.lampShadows ~= nil or vis.lampBrightness then
            for _, inst in ipairs(workspace:GetDescendants()) do
                if inst:IsA("Light") and not inst:IsDescendantOf(GUI) then
                    if lampStore[inst] == nil then
                        lampStore[inst] = { Brightness = inst.Brightness, Shadows = inst.Shadows }
                    end
                    if vis.lampShadows ~= nil then inst.Shadows = vis.lampShadows end
                    if vis.lampBrightness and vis.lampBrightness > 0 then inst.Brightness = vis.lampBrightness * 2 end
                end
            end
        end
    end

    local matStore = {}
    local function applyMaterials(reset)
        if reset or not vis.materialMode or string.lower(vis.materialMode) == "game" then
            for inst, mat in pairs(matStore) do
                if inst.Parent then pcall(function() inst.Material = mat end) end
            end
            matStore = {}
            return
        end
        local map = {
            plastic = Enum.Material.Plastic,
            smoothplastic = Enum.Material.SmoothPlastic,
            neon = Enum.Material.Neon,
            metal = Enum.Material.Metal,
            wood = Enum.Material.Wood,
            forcefield = Enum.Material.ForceField,
            glass = Enum.Material.Glass,
            concrete = Enum.Material.Concrete,
        }
        local mat = map[string.lower((tostring(vis.materialMode):gsub("%s", "")))]
        if not mat then return end
        local n = 0
        for _, inst in ipairs(workspace:GetDescendants()) do
            if inst:IsA("BasePart") and not (LP.Character and inst:IsDescendantOf(LP.Character)) then
                if matStore[inst] == nil then matStore[inst] = inst.Material end
                pcall(function() inst.Material = mat end)
                n = n + 1
                if n > 4000 then break end
            end
        end
    end

    local cursorGui, cursorDot
    local cursorHue, cursorSpinAngle, cursorPulsePhase = 0, 0, 0
    local function cursorApply()
        if not vis.cursorDirty then return end
        if not cursorGui then
            cursorGui = Instance.new("ScreenGui")
            cursorGui.Name = "KomaruCursor"
            cursorGui.IgnoreGuiInset = true
            cursorGui.ResetOnSpawn = false
            cursorGui.DisplayOrder = 2147483000
            cursorGui.Parent = LP:FindFirstChild("PlayerGui") or LP:WaitForChild("PlayerGui")
            cursorDot = Instance.new("Frame")
            cursorDot.Name = "Dot"
            cursorDot.Size = UDim2.fromOffset(22, 22)
            cursorDot.AnchorPoint = Vector2.new(0.5, 0.5)
            cursorDot.BackgroundColor3 = Color3.new(1, 1, 1)
            cursorDot.BorderSizePixel = 0
            cursorDot.ZIndex = 2
            cursorDot.Parent = cursorGui
            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(1, 0)
            corner.Parent = cursorDot
            local stroke = Instance.new("UIStroke")
            stroke.Name = "Outline"
            stroke.Thickness = 2
            stroke.Color = Color3.new(0, 0, 0)
            stroke.Transparency = 0.2
            stroke.Parent = cursorDot
            local grad = Instance.new("UIGradient")
            grad.Name = "Grad"
            grad.Parent = cursorDot
        end
        cursorGui.Enabled = true
    end

    local trail, trailA0, trailA1
    local function trailApply()
        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if vis.walkTrail and root and not trail then
            trailA0 = Instance.new("Attachment") trailA0.Position = Vector3.new(0, 1, 0) trailA0.Parent = root
            trailA1 = Instance.new("Attachment") trailA1.Position = Vector3.new(0, -1.5, 0) trailA1.Parent = root
            trail = Instance.new("Trail")
            trail.Attachment0 = trailA0
            trail.Attachment1 = trailA1
            trail.Lifetime = math.clamp(vis.trailFade or 3, 0.1, 20)
            trail.Color = ColorSequence.new(hex(vis.trailColor, Color3.fromRGB(120, 190, 255)))
            trail.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1 - math.clamp((vis.trailOpacity or 100) / 100, 0, 1)), NumberSequenceKeypoint.new(1, 1) })
            trail.WidthScale = NumberSequence.new({ NumberSequenceKeypoint.new(0, math.clamp((vis.trailSize or 100) / 100, 0.1, 5)), NumberSequenceKeypoint.new(1, 0) })
            trail.Parent = root
        elseif trail then
            trail.Lifetime = math.clamp(vis.trailLength or vis.trailFade or 3, 0.1, 20)
            local w = math.clamp((vis.trailWidth or vis.trailSize or 100) / 100, 0.1, 5)
            trail.WidthScale = NumberSequence.new({ NumberSequenceKeypoint.new(0, w), NumberSequenceKeypoint.new(1, 0) })
        end
        if not vis.walkTrail and trail then
            trail:Destroy()
            if trailA0 then trailA0:Destroy() end
            if trailA1 then trailA1:Destroy() end
            trail, trailA0, trailA1 = nil, nil, nil
        end
    end
    _G.KomaruTrailApply = trailApply

    local postStore = {}
    local function applyMuteEffects()
        if vis.muteFx then
            for _, c in ipairs(Lighting:GetChildren()) do
                if c:IsA("PostEffect") and not c:IsDescendantOf(fxFolder()) then
                    if postStore[c] == nil then postStore[c] = c.Enabled end
                    c.Enabled = false
                end
            end
        else
            for inst, en in pairs(postStore) do
                if inst.Parent then pcall(function() inst.Enabled = en end) end
            end
            postStore = {}
        end
    end

    local function applyAll()
        applyLighting()
        applyAir()
        applySky()
        applyCC()
        applyGlow()
        applyScreen()
        weatherApply()
        trailApply()
        cursorApply()
    end

    RunService.RenderStepped:Connect(function(dt)
        if not cursorGui or not cursorGui.Enabled then return end
        cursorSpinAngle = cursorSpinAngle + dt * math.rad(vis.cursorSpinSpeed or 180) * (vis.reverseSpin and -1 or 1)
        cursorPulsePhase = cursorPulsePhase + dt * (vis.cursorPulseSpeed or 3)
        cursorHue = cursorHue + dt * (vis.rainbowSpeed or 3)
        local pos = UIS:GetMouseLocation()
        local size = math.clamp((vis.cursorSize or 100) / 100, 0.2, 4) * 22
        if vis.cursorPulse then
            size = size * (1 + 0.12 * math.sin(cursorPulsePhase))
        end
        cursorDot.Size = UDim2.fromOffset(size, size)
        cursorDot.Position = UDim2.fromOffset(pos.X, pos.Y)
        if vis.rainbowCursor then
            cursorDot.BackgroundColor3 = Color3.fromHSV((cursorHue % 1), 0.85, 1)
        else
            cursorDot.BackgroundColor3 = hex(vis.cursorColor, Color3.new(1, 1, 1))
        end
        cursorDot.BackgroundTransparency = math.clamp((vis.cursorTransparency or 0) / 100, 0, 1)
        local stroke = cursorDot:FindFirstChild("Outline")
        if stroke then stroke.Transparency = vis.cursorOutline == false and 1 or 0.2 end
        local grad = cursorDot:FindFirstChild("Grad")
        if grad then grad.Rotation = math.deg(cursorSpinAngle) end
    end)

    function _G.KomaruVisReset()
        stopWeather()
        if cursorGui then cursorGui:Destroy() end
        cursorGui, cursorDot = nil, nil
        if trail then trail:Destroy() end
        if trailA0 then trailA0:Destroy() end
        if trailA1 then trailA1:Destroy() end
        trail, trailA0, trailA1 = nil, nil, nil
        for inst, en in pairs(postStore) do
            if inst.Parent then pcall(function() inst.Enabled = en end) end
        end
        postStore = {}
        for inst, mat in pairs(matStore) do
            if inst.Parent then pcall(function() inst.Material = mat end) end
        end
        matStore = {}
        for inst, st in pairs(lampStore) do
            if inst.Parent then
                pcall(function() inst.Brightness = st.Brightness end)
                pcall(function() inst.Shadows = st.Shadows end)
            end
        end
        lampStore = {}
        if vignette then vignette:Destroy() vignette = nil end
        if Lighting:FindFirstChild("KomaruFX") then Lighting:FindFirstChild("KomaruFX"):Destroy() end
        if base.done then
            for p, v in pairs(base) do
                if p ~= "done" then pcall(function() Lighting[p] = v end) end
            end
        end
        base = {}
        for k in pairs(vis) do vis[k] = nil end
        if cursorGui == nil then
            local pg = LP:FindFirstChild("PlayerGui")
            local old = pg and pg:FindFirstChild("KomaruCursor")
            if old then old:Destroy() end
        end
    end

    local F = function(label, fn) FEATURES[label] = fn end
    local function pass(key, flag)
        return function(v)
            if type(v) == "boolean" and flag then vis[flag] = v else vis[key] = v end
            applyAll()
        end
    end

    F("brightness", function(v)
        if type(v) == "boolean" then
            vis.brightnessOn = v
        else
            vis.lightLevel = v
            vis.ccBrightness = v
            vis.brightnessOn = true
        end
        applyAll()
    end)
    F("light level", function(v) vis.lightLevel = v if vis.brightnessOn then applyAll() end end)
    F("ambient level", function(v) vis.ambientLevel = v if vis.ambientOn then applyAll() end end)
    F("ambient light", pass("ambientTint", "ambientOn"))
    F("ambient tint", function(v) if type(v) == "string" then vis.ambientTint = v applyAll() end end)
    F("hour", function(v)
        if type(v) == "number" then vis.hour = v vis.hourSet = true
        elseif type(v) == "boolean" then vis.timeOfDay = v if v then vis.hourSet = true end end
        applyAll()
    end)
    F("time of day", function(v)
        if type(v) == "boolean" then vis.timeOfDay = v if v then vis.hourSet = true end
        elseif type(v) == "number" then vis.hour = v vis.hourSet = true end
        applyAll()
    end)
    F("latitude", function(v) vis.latitude = v vis.latSet = true applyAll() end)
    F("softness", function(v) vis.softness = v vis.softSet = true applyAll() end)
    F("no shadows", function(v) vis.noShadows = v applyAll() end)
    F("shaded", function(v) if type(v) == "string" then vis.shaded = v vis.lightColors = true applyAll() end end)
    F("sunlit", function(v) if type(v) == "string" then vis.sunlit = v vis.lightColors = true applyAll() end end)
    F("indoor", function(v) if type(v) == "string" then vis.indoor = v vis.lightColors = true applyAll() end end)
    F("outdoor", function(v) if type(v) == "string" then vis.outdoor = v vis.lightColors = true applyAll() end end)
    F("light colors", function(v) vis.lightColors = v applyAll() end)
    F("environment", function(v) vis.envOn = v applyAll() end)
    F("reflections", function(v) if type(v) == "number" then vis.reflections = v if vis.envOn then applyAll() end end end)
    F("diffuse light", function(v) if type(v) == "number" then vis.envOn = true vis.reflections = v applyAll() end end)
    F("exposure", function(v) vis.exposureOn = v applyAll() end)
    F("exposure level", function(v) vis.exposure = v if vis.exposureOn then applyAll() end end)
    F("lamp brightness", function(v) if type(v) == "number" then vis.lampBrightness = v applyLamps() end end)
    F("lamp shadows", function(v) vis.lampShadows = v applyLamps() end)
    F("atmosphere", function(v) vis.airOn = v applyAll() end)
    F("no atmosphere", function(v) vis.noAtmo = v applyAll() end)
    F("color", function(v) if type(v) == "string" then vis.airColor = v vis.skyColor = v applyAll() end end)
    F("density", function(v) if type(v) == "number" then vis.airDensity = v applyAll() end end)
    F("haze", function(v) if type(v) == "number" then vis.haze = v applyAll() end end)
    F("horizon", function(v) if type(v) == "string" then vis.airColor2 = v applyAll() end end)
    F("horizon offset", function(v) if type(v) == "number" then vis.horizonOffset = v applyAll() end end)
    F("sun glare", function(v) if type(v) == "number" then vis.sunGlare = v applyAll() end end)
    F("fog control", function(v) vis.fogOn = v applyAll() end)
    F("fog start", function(v) vis.fogStart = v if vis.fogOn then applyAll() end end)
    F("fog end", function(v) vis.fogEnd = v if vis.fogOn then applyAll() end end)
    F("sun & moon", function(v) vis.sunMoon = v vis.skyDirty = true applyAll() end)
    F("sun size", function(v) vis.sunSize = v vis.skyDirty = true applyAll() end)
    F("moon size", function(v) vis.moonSize = v vis.skyDirty = true applyAll() end)
    F("star count", function(v) vis.starCount = v vis.skyDirty = true applyAll() end)
    F("stars", function(v) vis.stars = v vis.skyDirty = true if not v then vis.starCount = 0 else vis.starCount = vis.starCount or 3000 end applyAll() end)
    F("color grading", function(v) vis.ccOn = v applyAll() end)
    F("saturation", function(v) if type(v) == "number" then vis.ccSaturation = v vis.ccOn = true applyAll() end end)
    F("contrast", function(v) if type(v) == "number" then vis.ccContrast = v vis.ccOn = true applyAll() end end)
    F("tint", function(v) if type(v) == "string" then vis.ccTint = v vis.ccOn = true applyAll() end end)
    F("style", function(v) if type(v) == "string" then vis.ccStyle = v vis.ccOn = true applyAll() end end)
    F("mute game effects", function(v) vis.muteFx = v applyMuteEffects() end)
    F("bloom", function(v) vis.bloom = v applyAll() end)
    F("glow intensity", function(v) vis.glowIntensity = v if vis.bloom then applyAll() end end)
    F("glow radius", function(v) vis.glowRadius = v if vis.bloom then applyAll() end end)
    F("glow threshold", function(v) vis.glowThreshold = v if vis.bloom then applyAll() end end)
    F("sun rays", function(v) vis.sunRays = v applyAll() end)
    F("ray intensity", function(v) vis.rayIntensity = v if vis.sunRays then applyAll() end end)
    F("ray spread", function(v) vis.raySpread = v if vis.sunRays then applyAll() end end)
    F("blur strength", function(v) vis.blurStrength = v vis.blurOn = v ~= nil and v > 0 applyAll() end)
    F("depth of field", function(v) vis.dofOn = v applyAll() end)
    F("focus distance", function(v) vis.focusDistance = v if vis.dofOn then applyAll() end end)
    F("sharp zone", function(v) vis.sharpZone = v if vis.dofOn then applyAll() end end)
    F("vignette", function(v) vis.vignette = v applyAll() end)
    F("edge shade", function(v) vis.edgeShade = v applyAll() end)
    F("enabled", function(v) vis.weatherOn = v applyAll() end)
    F("weather type", function(v) if type(v) == "string" then vis.weatherKind = v applyAll() end end)
    F("amount", function(v) vis.weatherAmount = v applyAll() end)
    F("visibility", function(v) vis.weatherVisibility = v applyAll() end)
    F("particle size", function(v) vis.weatherSize = v applyAll() end)
    F("weather volume", function(v) vis.weatherVolume = v end)
    F("weather sound", function(v) vis.weatherSound = v end)
    F("weather tint", function(v) vis.weatherTint = v end)
    F("wind strength", function(v) vis.windStrength = v applyAll() end)
    F("wind direction", function(v) vis.windAngle = v applyAll() end)
    F("gentle gusts", function(v) vis.gusts = v end)
    F("falling speed", function(v) vis.fallingSpeed = v end)
    F("materials", function(v) if type(v) == "string" then vis.materialMode = v applyMaterials() end end)
    F("no post effects", function(v)
        vis.noPost = v
        if v then
            for _, c in ipairs(Lighting:GetChildren()) do
                if c:IsA("PostEffect") and not c:IsDescendantOf(fxFolder()) then
                    if postStore[c] == nil then postStore[c] = c.Enabled end
                    c.Enabled = false
                end
            end
        else
            for inst, en in pairs(postStore) do if inst.Parent then pcall(function() inst.Enabled = en end) end end
            postStore = {}
        end
    end)
    F("no map lights", function(v)
        if v then
            for _, inst in ipairs(workspace:GetDescendants()) do
                if inst:IsA("Light") then
                    if lampStore[inst] == nil then lampStore[inst] = { Brightness = inst.Brightness, Shadows = inst.Shadows } end
                    inst.Enabled = false
                end
            end
        else
            for inst in pairs(lampStore) do if inst.Parent then pcall(function() inst.Enabled = true end) end end
        end
    end)
    F("plastic materials", function(v) vis.materialMode = v and "Plastic" or "Game" applyMaterials() end)
    F("fps cap", function(v) vis.fpsCap = v if type(setfpscap) == "function" and type(v) == "number" then pcall(setfpscap, v) end end)
    F("fps unlocker 9999", function(v) if type(setfpscap) == "function" then pcall(setfpscap, v and 9999 or 240) end end)
    F("low graphics", function(v)
        vis.lowGfx = v
        if v then
            for _, c in ipairs(Lighting:GetChildren()) do
                if c:IsA("PostEffect") then
                    if postStore[c] == nil then postStore[c] = c.Enabled end
                    c.Enabled = false
                end
            end
        else
            for inst, en in pairs(postStore) do if inst.Parent then pcall(function() inst.Enabled = en end) end end
            postStore = {}
        end
    end)
    F("cursor color", function(v) if type(v) == "string" then vis.cursorColor = v vis.cursorDirty = true end end)
    F("cursor outline", function(v) vis.cursorOutline = v vis.cursorDirty = true end)
    F("cursor pulse", function(v) vis.cursorPulse = v vis.cursorDirty = true end)
    F("cursor size", function(v) vis.cursorSize = v vis.cursorDirty = true end)
    F("cursor spin", function(v) vis.cursorSpin = v vis.cursorDirty = true end)
    F("cursor transparency", function(v) vis.cursorTransparency = v vis.cursorDirty = true end)
    F("rainbow cursor", function(v) vis.rainbowCursor = v vis.cursorDirty = true end)
    F("rainbow speed", function(v) vis.rainbowSpeed = v end)
    F("reverse spin", function(v) vis.reverseSpin = v end)
    F("spin speed", function(v) vis.cursorSpinSpeed = v end)
    F("pulse size", function(v) vis.cursorPulseAmt = v end)
    F("pulse speed", function(v) vis.cursorPulseSpeed = v end)
    F("click bounce", function(v) vis.clickBounce = v end)
    F("bounce size", function(v) vis.bounceSize = v end)
    F("walk trail", function(v) vis.walkTrail = v trailApply() end)
    F("trail custom color", function(v) vis.trailUseColor = v end)
    F("trail fade (s)", function(v) vis.trailFade = v trailApply() end)
    F("trail opacity", function(v) vis.trailOpacity = v trailApply() end)
    F("trail size", function(v) vis.trailSize = v trailApply() end)
    for _, entry in ipairs({
        { "ash color", "ashColour" },
        { "ember color", "emberColour" },
        { "firefly color", "fireflyColour" },
        { "leaf tint", "leafColour" },
        { "mist color", "mistColour" },
        { "petal tint", "petalColour" },
        { "pollen color", "pollenColour" },
        { "snow color", "snowColour" },
    }) do
        F(entry[1], function(v)
            if type(v) == "string" then
                vis.weatherCol = vis.weatherCol or {}
                vis.weatherCol[entry[2]] = v
                weatherApply()
            end
        end)
    end
end

--------------------------------------------------------------------------
-- pulse-parity: ESP v2 renderer (boxes / text / tracers / markers)
--------------------------------------------------------------------------
do
    local cfg = S.espCfg or {}
    S.espCfg = cfg
    local defaults = {
        boxOn = true, boxStyle = "Full", boxWidth = 60, padding = 1, thickness = 0.9,
        corner = 32, filled = true, fillStrength = 24, outlineColor = "000000",
        outlineOpacity = 90, outlineSize = 1, outline = true, glow = true,
        glowSize = 4, glowStrength = 4, glowColor = "ffffff", colorSource = "ESP",
        customColor = "ffffff", pulse = false, pulseSpeed = 1.2, animation = "None",
        animationSpeed = 1, names = true, nameSize = 12, nameCase = "Normal",
        nameFormat = "Display name", namePos = "Above", nameShadow = true,
        roleText = true, roleStyle = "Full", showDistance = true, distUnit = "Studs",
        detailSize = 9, detailCase = "UPPER", tracer = false, tracerOrigin = "Bottom",
        tracerTarget = "Center", tracerWidth = 2.2, tracerOpacity = 65,
        tracerColor = "ebebeb", tracerStyle = "Fade", markers = false, markerSize = 7,
        markerStyle = "Arrow", maxDist = 2000, boxMax = 0, nameMax = 0, fade = true,
        fadeStart = 63, visibility = false, opacity = 100, textScale = 93,
        lineScale = 178, gunEsp = false, xray = false,
    }
    for k, v in pairs(defaults) do
        if cfg[k] == nil then cfg[k] = v end
    end

    local cache = {}
    _G.KomaruESP = cache
    local visCache = {}
    local clock = 0

    local function hex(str, def)
        if type(str) ~= "string" then return def or Color3.new(1, 1, 1) end
        str = str:gsub("#", "")
        if #str < 6 then return def or Color3.new(1, 1, 1) end
        return Color3.fromRGB(tonumber(str:sub(1, 2), 16) or 255, tonumber(str:sub(3, 4), 16) or 255, tonumber(str:sub(5, 6), 16) or 255)
    end

    local function ensure(e, key, kind)
        if not e[key] then
            e[key] = newDraw(kind)
        end
        return e[key]
    end

    local function hide(e)
        for _, d in pairs(e) do
            if type(d) == "table" then
                for _, l in ipairs(d) do pcall(function() l.Visible = false end) end
            else
                pcall(function() d.Visible = false end)
            end
        end
    end

    local function destroy(e)
        for _, d in pairs(e) do
            if type(d) == "table" then
                for _, l in ipairs(d) do pcall(function() l:Remove() end) end
            else
                pcall(function() d:Remove() end)
            end
        end
    end

    local function visibleToCamera(player, char)
        local cam = workspace.CurrentCamera
        if not cam then return true end
        local now = os.clock()
        local c = visCache[player]
        if c and now - c[1] < 0.12 then return c[2] end
        local head = char:FindFirstChild("Head")
        if not head then return false end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local filter = { char }
        if LP.Character then filter[#filter+1] = LP.Character end
        params.FilterDescendantsInstances = filter
        local hit = workspace:Raycast(cam.CFrame.Position, head.Position - cam.CFrame.Position, params)
        local ok = hit == nil
        visCache[player] = { now, ok }
        return ok
    end

    local function roleAllowed(role)
        if role == "Murderer" then return S.espShowMurderer ~= false end
        if role == "Sheriff" then return S.espShowSheriff ~= false end
        return S.espShowInnocent ~= false
    end

    local function applyCase(txt)
        local c = cfg.nameCase
        if c == "UPPER" then return txt:upper() end
        if c == "lower" then return txt:lower() end
        return txt
    end

    RunService.RenderStepped:Connect(function(dt)
        clock = clock + dt
        if S.espV2 == false then return end
        if not S.esp then
            if next(cache) then
                for p, e in pairs(cache) do destroy(e) cache[p] = nil end
            end
            return
        end
        local cam = workspace.CurrentCamera
        if not cam then return end
        local vp = cam.ViewportSize
        local cx, cy = vp.X / 2, vp.Y / 2
        local maxDist = tonumber(cfg.maxDist) or 2000
        local fadeStart = math.clamp((tonumber(cfg.fadeStart) or 63) / 100, 0, 0.98)
        local alphaBase = math.clamp(1 - (tonumber(cfg.opacity) or 100) / 100, 0, 1)
        local lineScale = math.clamp((tonumber(cfg.lineScale) or 178) / 178, 0.3, 3)
        local textScale = math.clamp((tonumber(cfg.textScale) or 93) / 93, 0.4, 2.5)
        local seen = {}

        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LP and player.Character then
                local char = player.Character
                local root = char:FindFirstChild("HumanoidRootPart")
                local head = char:FindFirstChild("Head")
                local hum = char:FindFirstChildOfClass("Humanoid")
                if root and head and hum and hum.Health > 0 then
                    local role = getRole(player)
                    local dist = (root.Position - cam.CFrame.Position).Magnitude
                    local show = roleAllowed(role)
                        and (maxDist <= 0 or dist <= maxDist)
                        and (not cfg.visibility or visibleToCamera(player, char))
                    if show then
                        seen[player] = true
                        local e = cache[player]
                        if not e then
                            e = { corner = {} }
                            cache[player] = e
                        end
                        hide(e)
                        local top = head.Position + Vector3.new(0, 1.2, 0)
                        local bottom = root.Position - Vector3.new(0, 3, 0)
                        local topV, topOn = cam:WorldToViewportPoint(top)
                        local botV, botOn = cam:WorldToViewportPoint(bottom)
                        local roleColor = ROLE_COLORS[role] or ROLE_COLORS.Innocent
                        local color = cfg.colorSource == "Custom" and hex(cfg.customColor, roleColor) or roleColor
                        local fade = 0
                        if cfg.fade and maxDist > 0 then
                            local startD = maxDist * fadeStart
                            if dist > startD then
                                fade = math.clamp((dist - startD) / math.max(maxDist - startD, 1), 0, 1) * 0.85
                            end
                        end
                        local alpha = math.clamp(alphaBase + fade, 0, 1)
                        local lineW = math.max(0.5, (tonumber(cfg.thickness) or 0.9) * lineScale)
                        local ratio = math.clamp((tonumber(cfg.boxWidth) or 60) / 100, 0.2, 2)
                        local pad = math.clamp((tonumber(cfg.padding) or 1) / 100, -0.5, 0.5)
                        local onScreen = topOn and botOn
                        local h = onScreen and math.abs(botV.Y - topV.Y) or 0
                        local w = h * ratio
                        h = h * (1 + pad)
                        w = w * (1 + pad)
                        local bx = topV.X - w / 2
                        local by = topV.Y - (h - math.abs(botV.Y - topV.Y)) / 2
                        local boxOk = cfg.boxOn and (cfg.boxMax <= 0 or dist <= cfg.boxMax)
                        local pulseK = 0
                        if cfg.pulse or (cfg.animation and cfg.animation ~= "None") then
                            pulseK = (math.sin(clock * (tonumber(cfg.pulseSpeed) or 1.2)) * 0.5 + 0.5) * 0.9
                        end
                        if onScreen and boxOk then
                            local style = cfg.boxStyle
                            local box = ensure(e, "box", "Square")
                            if box then
                                box.Visible = style == "Full" or style == "Filled" or style == "3D"
                                box.Size = Vector2.new(w, h)
                                box.Position = Vector2.new(bx, by)
                                box.Color = color
                                box.Thickness = lineW + pulseK * 0.6
                                box.Transparency = alpha
                                box.Filled = false
                            end
                            if cfg.outline then
                                local o = ensure(e, "outline", "Square")
                                if o then
                                    o.Visible = style ~= "Corner"
                                    o.Size = Vector2.new(w + 2, h + 2)
                                    o.Position = Vector2.new(bx - 1, by - 1)
                                    o.Color = hex(cfg.outlineColor, Color3.new(0, 0, 0))
                                    o.Thickness = math.max(0.5, (tonumber(cfg.outlineSize) or 1) * lineScale)
                                    o.Transparency = math.clamp(1 - (tonumber(cfg.outlineOpacity) or 90) / 100 + fade, 0, 1)
                                    o.Filled = false
                                end
                            end
                            if cfg.glow then
                                local g = ensure(e, "glow", "Square")
                                if g then
                                    g.Visible = true
                                    g.Size = Vector2.new(w + (tonumber(cfg.glowSize) or 4) * 2, h + (tonumber(cfg.glowSize) or 4) * 2)
                                    g.Position = Vector2.new(bx - (tonumber(cfg.glowSize) or 4), by - (tonumber(cfg.glowSize) or 4))
                                    g.Color = cfg.colorSource == "Custom" and hex(cfg.customColor, color) or color
                                    g.Thickness = math.max(0.5, (tonumber(cfg.glowSize) or 4) * 0.5 * lineScale)
                                    g.Transparency = math.clamp(0.88 + fade * 0.1, 0, 1)
                                end
                            end
                            if cfg.filled and style ~= "Corner" then
                                local f = ensure(e, "fill", "Square")
                                if f then
                                    f.Visible = true
                                    f.Size = Vector2.new(w, h)
                                    f.Position = Vector2.new(bx, by)
                                    f.Color = color
                                    f.Thickness = 1
                                    f.Filled = true
                                    f.Transparency = math.clamp(1 - (tonumber(cfg.fillStrength) or 24) / 100 * 0.6 + fade, 0, 1)
                                end
                            end
                            if style == "Corner" then
                                local cw = w * math.clamp((tonumber(cfg.corner) or 32) / 100, 0.05, 0.5)
                                local pts = {
                                    { bx, by, bx + cw, by }, { bx, by, bx, by + cw },
                                    { bx + w, by, bx + w - cw, by }, { bx + w, by, bx + w, by + cw },
                                    { bx, by + h, bx + cw, by + h }, { bx, by + h, bx, by + h - cw },
                                    { bx + w, by + h, bx + w - cw, by + h }, { bx + w, by + h, bx + w, by + h - cw },
                                }
                                for i = 1, 8 do
                                    local l = e.corner[i]
                                    if not l then l = newDraw("Line") e.corner[i] = l end
                                    if l then
                                        l.Visible = true
                                        l.From = Vector2.new(pts[i][1], pts[i][2])
                                        l.To = Vector2.new(pts[i][3], pts[i][4])
                                        l.Color = color
                                        l.Thickness = lineW
                                        l.Transparency = alpha
                                    end
                                end
                            end
                        end

                        local nameOk = cfg.names and (cfg.nameMax <= 0 or dist <= cfg.nameMax)
                        local label = ""
                        if nameOk then
                            local nm = player.DisplayName
                            if cfg.nameFormat == "Username" then
                                nm = player.Name
                            elseif cfg.nameFormat == "Both" then
                                nm = player.DisplayName .. " (@" .. player.Name .. ")"
                            end
                            if cfg.hideNames then nm = "" end
                            local roleTxt = ""
                            if cfg.roleText then
                                roleTxt = role
                                if cfg.roleStyle == "Short" then roleTxt = role:sub(1, 1) end
                            end
                            label = applyCase(table.concat({ nm, roleTxt }, " "))
                        end
                        local detail = ""
                        if cfg.showDistance and nameOk then
                            local d = cfg.distUnit == "Meters" and (dist / 3.571) or dist
                            detail = string.format("%d%s", math.floor(d + 0.5), cfg.distUnit == "Meters" and "m" or " studs")
                        end
                        if onScreen then
                            local ns = math.clamp((tonumber(cfg.nameSize) or 12) * textScale, 7, 40)
                            local ds = math.clamp((tonumber(cfg.detailSize) or 9) * textScale, 6, 30)
                            local name = ensure(e, "name", "Text")
                            if name then
                                name.Visible = label ~= ""
                                name.Text = label
                                name.Size = ns
                                name.Center = true
                                name.Outline = cfg.nameShadow and true or false
                                name.Color = color
                                name.OutlineColor = hex(cfg.strokeColor, Color3.new(0, 0, 0))
                                local baseY = topV.Y - ns - 5
                                if cfg.namePos == "Below" then baseY = botV.Y + 5 end
                                name.Position = Vector2.new(topV.X, baseY)
                            end
                            local dtxt = ensure(e, "detail", "Text")
                            if dtxt then
                                dtxt.Visible = detail ~= ""
                                dtxt.Text = detail
                                dtxt.Size = ds
                                dtxt.Center = true
                                dtxt.Outline = true
                                dtxt.Color = color
                                dtxt.OutlineColor = hex(cfg.strokeColor, Color3.new(0, 0, 0))
                                local ns2 = math.clamp((tonumber(cfg.nameSize) or 12) * textScale, 7, 40)
                                local y = (cfg.namePos == "Below" and (botV.Y + 8 + ns2) or (topV.Y - 6))
                                dtxt.Position = Vector2.new(topV.X, y)
                            end
                        end

                        if cfg.tracer and onScreen then
                            local tr = ensure(e, "tracer", "Line")
                            if tr then
                                local ox, oy = cx, vp.Y
                                if cfg.tracerOrigin == "Top" then
                                    oy = 0
                                elseif cfg.tracerOrigin == "Center" then
                                    oy = cy
                                end
                                local tx, ty = topV.X, (topV.Y + botV.Y) / 2
                                if cfg.tracerTarget == "Bottom" then
                                    ty = botV.Y
                                elseif cfg.tracerTarget == "Top" then
                                    ty = topV.Y
                                end
                                tr.Visible = true
                                tr.From = Vector2.new(ox, oy)
                                tr.To = Vector2.new(tx, ty)
                                tr.Color = cfg.tracerColor and hex(cfg.tracerColor, color) or color
                                tr.Thickness = math.max(0.5, (tonumber(cfg.tracerWidth) or 2.2) * lineScale)
                                tr.Transparency = math.clamp(1 - (tonumber(cfg.tracerOpacity) or 65) / 100 + fade, 0, 1)
                            end
                        end

                        if cfg.markers and not onScreen then
                            local dx, dy = topV.X - cx, topV.Y - cy
                            if dx == 0 and dy == 0 then dx = 1 end
                            local scale = math.min((cx - 46) / math.max(math.abs(dx), 1), (cy - 46) / math.max(math.abs(dy), 1))
                            scale = math.max(scale, 0)
                            local px, py = cx + dx * scale, cy + dy * scale
                            local len = math.max(4, (tonumber(cfg.markerSize) or 7) * 1.6)
                            local ux, uy = dx, dy
                            local m = math.sqrt(ux * ux + uy * uy)
                            ux, uy = ux / m, uy / m
                            local tri = ensure(e, "marker", "Triangle")
                            if tri then
                                tri.Visible = true
                                tri.Color = color
                                tri.Thickness = 1
                                tri.Transparency = alpha
                                if cfg.markerStyle == "Dot" then
                                    tri.PointA = Vector2.new(px - 3, py - 3)
                                    tri.PointB = Vector2.new(px + 3, py - 3)
                                    tri.PointC = Vector2.new(px, py + 3)
                                else
                                    tri.PointA = Vector2.new(px + ux * len, py + uy * len)
                                    tri.PointB = Vector2.new(px - uy * len * 0.62, py + ux * len * 0.62)
                                    tri.PointC = Vector2.new(px + uy * len * 0.62, py - ux * len * 0.62)
                                end
                            end
                        end
                    end
                end
            end
        end
        for p, e in pairs(cache) do
            if not seen[p] then
                destroy(e)
                cache[p] = nil
                visCache[p] = nil
            end
        end
    end)

    Players.PlayerRemoving:Connect(function(p)
        local e = cache[p]
        if e then destroy(e) cache[p] = nil end
        visCache[p] = nil
    end)

    local function set(key, field)
        return function(v)
            if type(v) == "boolean" or type(v) == "number" or type(v) == "string" then
                cfg[field or key] = v
            end
        end
    end
