--------------------------------------------------------------------------
-- pulse-parity: combat v2 (aim / fov / kill aura / auto throw / tracers)
--------------------------------------------------------------------------
do
    local cfg = S.combatCfg or {}
    S.combatCfg = cfg
    local defaults = {
        aimFov = 360, maxDist = 250, wallCheck = true, predict = true, sticky = true,
        targetMode = "Smart", lead = 100, autoRange = 70, minChance = 55,
        aimType = "Classic", sideProfile = true, flickSpeed = 6, flickReturn = 100,
        fovShow = false, fovColor = "78dcff", fovSize = 220, fovTransparency = 20,
        fovFilled = false, autoThrow = false, auraRadius = 20, tracers = false,
        tracerColor = "6ebeff", tracerWidth = 100, tracerDuration = 1.2,
        knifeTracerColor = "ff3c5a", knifeTracerWidth = 100, knifeTracerDuration = 1.2,
        impact = true, muzzle = true, predMs = 0, killSound = "Off", shotSound = "Off",
        soundVolume = 60, stickyTime = 1.5,
    }
    for k, v in pairs(defaults) do
        if cfg[k] == nil then cfg[k] = v end
    end

    local sticky, stickyAt = nil, 0
    local tracers = {}
    local fovLine, fovCircle

    local function hex(str, def)
        if type(str) ~= "string" then return def or Color3.new(1, 1, 1) end
        str = str:gsub("#", "")
        if #str < 6 then return def or Color3.new(1, 1, 1) end
        return Color3.fromRGB(tonumber(str:sub(1, 2), 16) or 255, tonumber(str:sub(3, 4), 16) or 255, tonumber(str:sub(5, 6), 16) or 255)
    end

    local function blocked(from, to, char)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local filter = { char }
        if LP.Character then filter[#filter+1] = LP.Character end
        params.FilterDescendantsInstances = filter
        local hit = workspace:Raycast(from, to - from, params)
        return hit ~= nil
    end

    local function myRole()
        local ok, r = pcall(getRole, LP)
        return ok and r or "Innocent"
    end

    local function roleScore(role)
        local me = myRole()
        if me == "Murderer" then
            if role == "Sheriff" then return 1 end
            if role == "Innocent" then return 2 end
            return 3
        elseif me == "Sheriff" then
            if role == "Murderer" then return 1 end
            if role == "Innocent" then return 3 end
            return 2
        end
        if role == "Murderer" then return 1 end
        if role == "Sheriff" then return 2 end
        return 3
    end

    local function pick(radius)
        local cam = workspace.CurrentCamera
        if not cam then return nil end
        local best, bestScore
        local now = os.clock()
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character then
                local head = p.Character:FindFirstChild("Head")
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if head and hum and hum.Health > 0 then
                    local role = getRole(p)
                    local dist = (head.Position - cam.CFrame.Position).Magnitude
                    local limit = radius or cfg.maxDist
                    if limit <= 0 or dist <= limit then
                        local ok = true
                        if not radius and cfg.aimFov < 360 then
                            local dir = (head.Position - cam.CFrame.Position).Unit
                            local ang = math.deg(math.acos(math.clamp(cam.CFrame.LookVector:Dot(dir), -1, 1)))
                            if ang > cfg.aimFov / 2 then ok = false end
                        end
                        if ok and cfg.wallCheck and blocked(cam.CFrame.Position, head.Position, p.Character) then ok = false end
                        if ok then
                            local score = dist + roleScore(role) * 40
                            if sticky == p and now - stickyAt < (cfg.stickyTime or 1.5) then score = score - 150 end
                            if not bestScore or score < bestScore then
                                best, bestScore = { head = head, player = p }, score
                            end
                        end
                    end
                end
            end
        end
        if best and cfg.sticky ~= false then
            sticky, stickyAt = best.player, os.clock()
        end
        return best and best.head, best and best.player
    end

    local function leadPoint(head, player)
        if cfg.predict == false then return head.Position end
        local ping = 0.06
        pcall(function() ping = player:GetNetworkPing() end)
        local extra = (tonumber(cfg.predMs) or 0) / 1000
        local v = head.AssemblyLinearVelocity
        return head.Position + v * math.clamp((ping + extra) * (cfg.lead / 100), 0, 0.5)
    end

    local function face(targetPos)
        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local look = Vector3.new(targetPos.X, root.Position.Y, targetPos.Z)
        if (look - root.Position).Magnitude < 0.2 then return end
        local cf = CFrame.new(root.Position, look)
        if cfg.sideProfile then cf = cf * CFrame.Angles(0, math.rad(72), 0) end
        local k = math.clamp((tonumber(cfg.flickSpeed) or 6) / 20, 0.08, 1)
        root.CFrame = root.CFrame:Lerp(cf, k)
    end

    local function findTool(char, needle)
        local function scan(container)
            if not container then return nil end
            for _, t in ipairs(container:GetChildren()) do
                if t:IsA("Tool") and string.find(string.lower(t.Name), needle, 1, true) then return t end
            end
            return nil
        end
        return scan(char) or scan(LP:FindFirstChild("Backpack"))
    end

    local function anyTool(char)
        local t = char:FindFirstChildOfClass("Tool")
        if t then return t end
        local bp = LP:FindFirstChild("Backpack")
        return bp and bp:FindFirstChildOfClass("Tool") or nil
    end

    local function drawTracer(fromWorld, toWorld, colorStr, width)
        local cam = workspace.CurrentCamera
        if not cam then return end
        local a, aOn = cam:WorldToViewportPoint(fromWorld)
        local b, bOn = cam:WorldToViewportPoint(toWorld)
        if not aOn and not bOn then
            a, b = Vector3.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y), Vector3.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
        end
        local line = newDraw("Line")
        if not line then return end
        line.From = Vector2.new(a.X, a.Y)
        line.To = Vector2.new(b.X, b.Y)
        line.Color = hex(colorStr, Color3.fromRGB(110, 190, 255))
        line.Thickness = math.max(0.5, (tonumber(width) or 100) / 100 * 1.8)
        line.Transparency = 0.1
        line.Visible = true
        tracers[#tracers+1] = { line = line, t0 = os.clock(), dur = tonumber(cfg.tracerDuration) or 1.2 }
    end

    local function muzzleFlash(char)
        if not cfg.muzzle then return end
        local tool = char and char:FindFirstChildOfClass("Tool")
        local handle = tool and tool:FindFirstChild("Handle")
        if handle then
            local light = Instance.new("PointLight")
            light.Brightness = 6
            light.Range = 9
            light.Color = Color3.fromRGB(255, 226, 160)
            light.Parent = handle
            task.delay(0.07, function() pcall(function() light:Destroy() end) end)
        end
    end

    local function drawFov()
        local cam = workspace.CurrentCamera
        if not cam then return end
        local vp = cam.ViewportSize
        local radius = math.max(10, (tonumber(cfg.fovSize) or 220) / 2 * (vp.Y / 1080))
        local col = hex(cfg.fovColor, Color3.fromRGB(120, 220, 255))
        local alpha = math.clamp((tonumber(cfg.fovTransparency) or 20) / 100, 0, 1)
        if not fovCircle then
            local ok, c = pcall(function() return Drawing.new("Circle") end)
            if ok then fovCircle = c end
        end
        if fovCircle then
            fovCircle.Visible = cfg.fovShow and true or false
            fovCircle.Position = Vector2.new(vp.X / 2, vp.Y / 2)
            fovCircle.Radius = radius
            fovCircle.Thickness = 1.5
            fovCircle.Color = col
            fovCircle.Transparency = alpha
            fovCircle.Filled = cfg.fovFilled and true or false
            fovCircle.NumSides = 64
            return
        end
        if not fovLine then fovLine = {} end
        local segs = 48
        for i = 1, segs do
            local l = fovLine[i]
            if not l then l = newDraw("Line") fovLine[i] = l end
            if l then
                local a1 = (i - 1) / segs * math.pi * 2
                local a2 = i / segs * math.pi * 2
                l.Visible = cfg.fovShow and true or false
                l.From = Vector2.new(vp.X / 2 + math.cos(a1) * radius, vp.Y / 2 + math.sin(a1) * radius)
                l.To = Vector2.new(vp.X / 2 + math.cos(a2) * radius, vp.Y / 2 + math.sin(a2) * radius)
                l.Color = col
                l.Thickness = 1.5
                l.Transparency = alpha
            end
        end
    end

    RunService.RenderStepped:Connect(function()
        if not alive() then return end
        if S.combatV2 == false then return end
        if cfg.fovShow then
            drawFov()
        else
            if fovCircle then fovCircle.Visible = false end
            if fovLine then
                for _, l in ipairs(fovLine) do pcall(function() l.Visible = false end) end
            end
        end
        if S.aimbot or S.silentAim or S.knifeAimbot then
            local head, player = pick()
            if head and player then
                local pos = leadPoint(head, player)
                if not S.silentAim then face(pos) end
            end
        end
        local now = os.clock()
        for i = #tracers, 1, -1 do
            local tr = tracers[i]
            local e = now - tr.t0
            if e > tr.dur then
                pcall(function() tr.line:Remove() end)
                table.remove(tracers, i)
            else
                pcall(function()
                    tr.line.Transparency = math.clamp(e / tr.dur, 0, 1)
                    tr.line.Thickness = math.max(0.5, tr.line.Thickness * 0.992)
                end)
            end
        end
    end)

    task.spawn(function()
        while task.wait(0.12) do
            if not alive() then return end
            if S.combatV2 == false then return end
            local char = LP.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not root then continue end
            local knife = findTool(char, "knife")
            if S.killAura then
                local head = pick(cfg.auraRadius)
                if head then
                    local tool = knife or anyTool(char)
                    if tool then
                        pcall(function() tool:Activate() end)
                    end
                end
            end
            if S.autoThrow and (knife or myRole() == "Murderer") then
                local head, player = pick()
                if head then
                    local pos = leadPoint(head, player)
                    local d = (head.Position - root.Position).Magnitude
                    if d <= cfg.autoRange and d > 4 then
                        face(pos)
                        if knife then
                            pcall(function() knife:Activate() end)
                            drawTracer(root.Position, pos, cfg.knifeTracerColor, cfg.knifeTracerWidth)
                        end
                    end
                end
            end
            if S.autoShoot then
                local gun = findTool(char, "gun")
                if gun then
                    local head, player = pick()
                    if head then
                        local pos = leadPoint(head, player)
                        face(pos)
                        pcall(function() gun:Activate() end)
                        muzzleFlash(char)
                        drawTracer(root.Position + Vector3.new(0, 1, 0), pos, cfg.tracerColor, cfg.tracerWidth)
                    end
                end
            end
        end
    end)

    local F = function(label, fn) FEATURES[label] = fn end
    local function set(key)
        return function(v)
            if type(v) == "boolean" or type(v) == "number" or type(v) == "string" then cfg[key] = v end
        end
    end
    F("aimbot", function(v) S.aimbot = v end)
    F("aim bot", FEATURES["aimbot"])
    F("silent aim", function(v) S.silentAim = v end)
    F("silentaim", FEATURES["silent aim"])
    F("kill aura", function(v) S.killAura = v end)
    F("killaura", FEATURES["kill aura"])
    F("auto shoot murder", function(v) S.autoShoot = v end)
    F("auto shoot", FEATURES["auto shoot murder"])
    F("auto throw", function(v) S.autoThrow = v cfg.autoThrow = v end)
    F("knife throw aimbot", function(v) S.knifeAimbot = v end)
    F("aim fov", set("aimFov"))
    F("aimbot fov", FEATURES["aim fov"])
    F("fov", FEATURES["aim fov"])
    F("max distance", function(v)
        cfg.maxDist = v
        S.maxDist = v
        if S.espCfg then S.espCfg.maxDist = v end
    end)
    F("aura radius", function(v) cfg.auraRadius = v S.killRange = v end)
    F("auto range", set("autoRange"))
    F("auto min chance %", set("minChance"))
    F("wall check", set("wallCheck"))
    F("predict movement", set("predict"))
    F("sticky target", set("sticky"))
    F("target mode", set("targetMode"))
    F("lead %", set("lead"))
    F("aimbot type", set("aimType"))
    F("side profile", set("sideProfile"))
    F("flick speed", set("flickSpeed"))
    F("flick return %", set("flickReturn"))
    F("flick with mouse", set("flickMouse"))
    F("prediction (ms)", set("predMs"))
    F("show fov circle", set("fovShow"))
    F("fov size", set("fovSize"))
    F("fov color", set("fovColor"))
    F("fov transparency", set("fovTransparency"))
    F("filled", set("fovFilled"))
    F("lock color", set("lockColor"))
    F("bullet tracers", function(v) cfg.tracers = v S.bulletTracers = v end)
    F("knife tracers", function(v) S.knifeTracers = v end)
    F("tracer color", set("tracerColor"))
    F("tracer width", set("tracerWidth"))
    F("tracer duration", set("tracerDuration"))
    F("tracer method", set("tracerMethod"))
    F("knife tracer color", set("knifeTracerColor"))
    F("knife tracer width", set("knifeTracerWidth"))
    F("knife tracer duration", set("knifeTracerDuration"))
    F("impact effect", set("impact"))
    F("muzzle flash", set("muzzle"))
    F("kill sound", set("killSound"))
    F("shot sound", set("shotSound"))
    F("sound volume", set("soundVolume"))
