--------------------------------------------------------------------------
-- pulse-parity: on-screen quick buttons (Mobile tab)
--------------------------------------------------------------------------
do
    local cfg = S.mobileCfg or {}
    S.mobileCfg = cfg
    local sizes = {}
    local defaults = {
        fly = false, noclip = false, invis = false, bhop = false, speed = false,
        glitch = false, killAll = false, knifeThrow = false, shotMurder = false,
        flingMurderer = false, flingSheriff = false, autoBomb = false,
    }
    for k, v in pairs(defaults) do
        if cfg[k] == nil then cfg[k] = v end
    end
    cfg.pos = cfg.pos or {}
    cfg.on = cfg.on or {}
    local gui, buttons, meta = nil, {}, {}
    local dragging = nil

    local function ensureGui()
        if gui and gui.Parent then return gui end
        local pg = LP:FindFirstChild("PlayerGui")
        if pg then
            for _, old in ipairs(pg:GetChildren()) do
                if old.Name == "KomaruMobile" then pcall(function() old:Destroy() end) end
            end
        end
        gui = Instance.new("ScreenGui")
        gui.Name = "KomaruMobile"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.DisplayOrder = 2147482000
        gui.Parent = LP:FindFirstChild("PlayerGui") or LP:WaitForChild("PlayerGui")
        return gui
    end

    local defs = {
        { key = "fly", label = "Fly", feat = "fly", color = Color3.fromRGB(255, 122, 26) },
        { key = "noclip", label = "Noclip", feat = "no clip", color = Color3.fromRGB(90, 200, 255) },
        { key = "invis", label = "Invis", feat = "invisible", color = Color3.fromRGB(180, 140, 255) },
        { key = "bhop", label = "Bhop", feat = "bhop", color = Color3.fromRGB(120, 230, 150) },
        { key = "speed", label = "Speed", feat = "walk speed", color = Color3.fromRGB(255, 200, 80) },
        { key = "glitch", label = "Glitch", feat = "speed glitch", color = Color3.fromRGB(255, 110, 140) },
        { key = "killAll", label = "Kill All", feat = "kill all", color = Color3.fromRGB(240, 70, 70) },
        { key = "knifeThrow", label = "Throw", feat = "auto throw", color = Color3.fromRGB(255, 150, 90) },
        { key = "shotMurder", label = "Shoot", feat = "auto shoot murder", color = Color3.fromRGB(110, 190, 255) },
        { key = "flingMurderer", label = "Fling M", feat = "click fling", color = Color3.fromRGB(220, 120, 255) },
        { key = "flingSheriff", label = "Fling S", feat = "click fling", color = Color3.fromRGB(140, 160, 255) },
        { key = "autoBomb", label = "Bomb Jump", feat = "bomb jump", color = Color3.fromRGB(255, 170, 60) },
    }

    local function applyState(key, on)
        local b = buttons[key]
        local m = meta[key]
        if not (b and m) then return end
        m.on = on
        b.BackgroundColor3 = on and m.color or Color3.fromRGB(28, 26, 24)
        b.TextColor3 = on and Color3.fromRGB(20, 18, 16) or Color3.fromRGB(235, 232, 228)
        if m.stroke then m.stroke.Transparency = on and 0 or 0.55 end
    end

    local function toggle(key)
        local m = meta[key]
        if not m then return end
        local on = not m.on
        cfg.on[key] = on
        applyState(key, on)
        local fn = FEATURES[m.feat]
        if fn then pcall(fn, on) end
    end

    local function make(key)
        local def
        for _, d in ipairs(defs) do
            if d.key == key then def = d break end
        end
        if not def then return end
        ensureGui()
        local b = Instance.new("TextButton")
        b.Name = "Btn_" .. key
        b.Text = def.label
        b.Font = Enum.Font.GothamBold
        b.TextSize = 13
        b.TextColor3 = Color3.fromRGB(235, 232, 228)
        b.BackgroundColor3 = Color3.fromRGB(28, 26, 24)
        b.AutoButtonColor = false
        b.BorderSizePixel = 0
        b.Size = UDim2.fromOffset(58, 34)
        b.Position = UDim2.fromOffset(20, 120 + #defs * 4 + (#buttons) * 44)
        b.Parent = gui
        local pos = cfg.pos[key]
        if pos then
            b.Position = UDim2.fromOffset(pos[1], pos[2])
        end
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 10)
        corner.Parent = b
        local stroke = Instance.new("UIStroke")
        stroke.Thickness = 1
        stroke.Color = def.color
        stroke.Transparency = 0.55
        stroke.Parent = b
        meta[key] = { color = def.color, feat = def.feat, on = false, stroke = stroke }
        b.MouseButton1Click:Connect(function()
            toggle(key)
        end)
        b.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = { btn = b, key = key, start = input.Position, base = b.Position }
            end
        end)
        b.InputEnded:Connect(function(input)
            if dragging and dragging.btn == b then
                cfg.pos[key] = { b.Position.X.Offset, b.Position.Y.Offset }
                dragging = nil
            end
        end)
        buttons[key] = b
        applyState(key, cfg.on[key] and true or false)
    end

    local function syncAll()
        for _, d in ipairs(defs) do
            if cfg[d.key] then
                if not buttons[d.key] then make(d.key) end
                if buttons[d.key] then
                    buttons[d.key].Visible = true
                    applyState(d.key, cfg.on[d.key] and true or false)
                end
            elseif buttons[d.key] then
                buttons[d.key].Visible = false
            end
        end
        if not cfg.fly and not cfg.noclip and not cfg.invis and not cfg.bhop and not cfg.speed
            and not cfg.glitch and not cfg.killAll and not cfg.knifeThrow and not cfg.shotMurder
            and not cfg.flingMurderer and not cfg.flingSheriff and not cfg.autoBomb then
            if gui then gui.Enabled = false end
        elseif gui then
            gui.Enabled = true
        else
            ensureGui()
        end
    end

    UIS.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local delta = input.Position - dragging.start
        dragging.btn.Position = UDim2.fromOffset(dragging.base.X.Offset + delta.X, dragging.base.Y.Offset + delta.Y)
    end)
    UIS.InputEnded:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
            cfg.pos[dragging.key] = { dragging.btn.Position.X.Offset, dragging.btn.Position.Y.Offset }
            dragging = nil
        end
    end)

    local keyOf = {
        ["fly button"] = "fly", ["no clip button"] = "noclip", ["invisible button"] = "invis",
        ["bhop button"] = "bhop", ["speed button"] = "speed", ["speed glitch button"] = "glitch",
        ["kill all murder button"] = "killAll", ["knife throw button"] = "knifeThrow",
        ["shot murder button"] = "shotMurder", ["fling murderer button"] = "flingMurderer",
        ["fling sheriff button"] = "flingSheriff", ["auto bomb jump button"] = "autoBomb",
    }
    local sizeKey = {
        ["fly button size"] = "fly", ["no clip button size"] = "noclip",
        ["invisible button size"] = "invis", ["bhop button size"] = "bhop",
        ["speed button size"] = "speed", ["speed glitch button size"] = "glitch",
        ["kill all murder button size"] = "killAll", ["knife throw button size"] = "knifeThrow",
        ["shot murder button size"] = "shotMurder", ["fling murderer button size"] = "flingMurderer",
        ["fling sheriff button size"] = "flingSheriff", ["auto bomb jump button size"] = "autoBomb",
    }

    for label, key in pairs(keyOf) do
        FEATURES[label] = function(v)
            cfg[key] = v and true or false
            syncAll()
        end
    end
    for label, key in pairs(sizeKey) do
        FEATURES[label] = function(v)
            local scale = math.clamp((tonumber(v) or 100) / 100, 0.5, 2)
            local b = buttons[key]
            if b then b.Size = UDim2.fromOffset(58 * scale, 34 * scale) b.TextSize = math.floor(13 * scale) end
            cfg[key .. "Scale"] = scale
        end
    end

    FEATURES["reset uis position"] = function()
        cfg.pos = {}
        for k, b in pairs(buttons) do
            b.Position = UDim2.fromOffset(20, 200)
        end
        toast("Позиции кнопок сброшены")
    end
    FEATURES["unlock all buttons"] = function()
        for k, b in pairs(buttons) do
            b.Visible = true
        end
        toast("Кнопки разблокированы")
    end
    FEATURES["double tap lock"] = function(v) cfg.doubleTapLock = v end
    FEATURES["show ping/fps ui"] = function(v) S.showFps = v end
    FEATURES["show round timer"] = function(v) cfg.roundTimer = v end

    task.spawn(function()
        while task.wait(0.6) do
            if not alive() then return end
            pcall(syncAll)
        end
    end)
end

