    -- night sky / magic / particle knobs
    local sky = vis.skyExtras or {}
    vis.skyExtras = sky
    local skyDefaults = {
        clouds = false, comets = false, constellations = false, runes = false,
        stardust = false, shootingStars = false, starFigures = false,
        cloudCover = 40, cloudDensity = 30, cometFreq = 3, cometSize = 100,
        meteorFreq = 4, nodeCount = 8, runeAmount = 12, runeSize = 100,
        starDensity = 50, starSize = 100, starColor = "ffffff",
        dustColor = "cfe6ff", dustAmount = 30, driftSpeed = 25,
        tailLength = 60, twinkle = true, effectBrightness = 100,
        textureSize = 100, particleRate = 20, coverage = 60, height = 120,
        lineLength = 100, linkDistance = 45, manualDelay = 0,
    }
    for k, v in pairs(skyDefaults) do if sky[k] == nil then sky[k] = v end end

    local skyPart, emitters = nil, {}
    local function skyFolder()
        local f = workspace:FindFirstChild("KomaruSkyExtras")
        if not f then
            f = Instance.new("Folder")
            f.Name = "KomaruSkyExtras"
            f.Parent = workspace
        end
        return f
    end
    local function skyApply()
        local folder = skyFolder()
        if skyPart and skyPart.Parent then skyPart:Destroy() end
        skyPart = nil
        for name, e in pairs(emitters) do
            if e.Parent then e.Parent = nil end
            emitters[name] = nil
        end
        local any = sky.clouds or sky.comets or sky.constellations or sky.runes or sky.stardust or sky.shootingStars or sky.starFigures
        if not any then return end
        skyPart = Instance.new("Part")
        skyPart.Name = "SkyEmitter"
        skyPart.Anchored = true
        skyPart.CanCollide = false
        skyPart.CanQuery = false
        skyPart.Transparency = 1
        skyPart.Size = Vector3.new(1, 1, 1)
        skyPart.Parent = folder
        local cam = workspace.CurrentCamera
        local pos = cam and cam.CFrame.Position or Vector3.new(0, 60, 0)
        skyPart.Position = pos + Vector3.new(0, 90, 0)

        local function add(name, texture, rate, size, speed, color)
            local e = Instance.new("ParticleEmitter")
            e.Name = name
            e.Texture = texture
            e.Rate = rate
            e.Lifetime = NumberRange.new(3, 7)
            e.Speed = NumberRange.new(speed * 0.6, speed)
            e.SpreadAngle = Vector2.new(180, 180)
            e.Size = NumberSequence.new(size * (sky.starSize or 100) / 100)
            e.Transparency = NumberSequence.new(0.35)
            e.LightEmission = 1
            e.Color = ColorSequence.new(color)
            e.Parent = skyPart
            emitters[name] = e
            return e
        end
        if sky.stardust or sky.constellations or sky.starFigures then
            add("Stardust", "rbxasset://textures/particles/sparkles_main.dds",
                math.clamp((sky.starDensity or 50) / 5, 1, 120), 1.2, 0.6,
                col(sky.starColor, Color3.fromRGB(220, 235, 255)))
        end
        if sky.clouds then
            local c = add("Clouds", "rbxasset://textures/particles/smoke_main.dds",
                math.clamp((sky.cloudCover or 40) / 4, 1, 40), 40, 1.2,
                Color3.fromRGB(200, 205, 220))
            c.Transparency = NumberSequence.new(0.82)
            c.LightEmission = 0
            c.Lifetime = NumberRange.new(20, 40)
        end
        if sky.comets or sky.shootingStars then
            local m = add("Comets", "rbxasset://textures/particles/sparkles_main.dds",
                math.clamp((sky.cometFreq or 3) * 2, 1, 40), 2.5, 8,
                Color3.fromRGB(255, 240, 200))
            m.Lifetime = NumberRange.new(0.6, 1.4)
            m.SpreadAngle = Vector2.new(20, 20)
        end
        if sky.runes then
            add("Runes", "rbxasset://textures/particles/sparkles_main.dds",
                math.clamp((sky.runeAmount or 12) / 2, 1, 60), 1.6, 0.3,
                Color3.fromRGB(170, 130, 255))
        end
    end

