    -- kill sounds
    local function playKill()
        if not S.killSounds then return end
        local s = Instance.new("Sound")
        s.SoundId = "rbxassetid://12221967"
        s.Volume = math.clamp((tonumber(S.killVolume) or 60) / 100, 0, 3)
        s.Parent = game:GetService("SoundService")
        s:Play()
        task.delay(3, function() pcall(function() s:Destroy() end) end)
    end
    task.spawn(function()
        while alive() do
            local pl = LP.Character
            local hum = pl and pl:FindFirstChildOfClass("Humanoid")
            if hum then
                hum.Died:Connect(playKill)
            end
            local conns = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LP then
                    local function hook(c)
                        local h = c and c:FindFirstChildOfClass("Humanoid")
                        if h then h.Died:Connect(playKill) end
                    end
                    if p.Character then hook(p.Character) end
                    p.CharacterAdded:Connect(hook)
                end
            end
            task.wait(2)
        end
    end)

