    -- screen shake / follow cursor / tone mapping
    local shakeT = 0
    RunService.RenderStepped:Connect(function(dt)
        if not alive() then return end
        if S.screenShake and shakeT > 0 then
            shakeT = shakeT - dt
            local cam = workspace.CurrentCamera
            if cam then
                local a = shakeT * 0.6
                cam.CFrame = cam.CFrame * CFrame.Angles(math.sin(tick() * 60) * a * 0.01, math.cos(tick() * 57) * a * 0.01, 0)
            end
        end
        local fc = _G.KomaruFollowLine
        if S.followCursor then
            local cam = workspace.CurrentCamera
            local root = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if cam and root then
                if not fc then
                    local ok, l = pcall(function() return Drawing.new("Line") end)
                    if ok then fc = l _G.KomaruFollowLine = fc end
                end
                if fc then
                    local a = cam:WorldToViewportPoint(root.Position)
                    local m = UIS:GetMouseLocation()
                    fc.Visible = true
                    fc.From = Vector2.new(a.X, a.Y)
                    fc.To = Vector2.new(m.X, m.Y)
                    fc.Color = Color3.fromRGB(255, 180, 90)
                    fc.Thickness = 1.4
                    fc.Transparency = 0.35
                end
            elseif fc then
                fc.Visible = false
            end
        elseif fc then
            fc.Visible = false
        end
    end)
    F("screen shake", function(v)
        S.screenShake = v
        if v then shakeT = 1.2 end
    end)

