                    local hit = workspace:Raycast(cam.CFrame.Position, Vector3.new(0, 40, 0), params)
                    local weather = workspace:FindFirstChild("KomaruWeather")
                    if weather then weather:SetAttribute("KomaruPaused", hit ~= nil) end
                end
            end
        end
    end)
end

