-- runtime audit: every visible Row label must have a FEATURES handler
_G.KomaruAuditRows = function()
    local out = { total = 0, found = 0, missing = {} }
    local seen = {}
    for _, tab in ipairs(BODY:GetChildren()) do
        if tab:IsA("CanvasGroup") then
            for _, d in ipairs(tab:GetDescendants()) do
                if d:IsA("Frame") and d.Name == "Row" then
                    local lbl
                    for _, c in ipairs(d:GetChildren()) do
                        if c:IsA("TextLabel") and norm(c.Text) ~= "" then lbl = norm(c.Text) break end
                    end
                    if not lbl then
                        local right = d:FindFirstChild("Right")
                        local b = d:FindFirstChild("Button") or (right and right:FindFirstChild("Button", true))
                        if b then
                            for _, x in ipairs(b:GetDescendants()) do
                                if x:IsA("TextLabel") and norm(x.Text) ~= "" then lbl = norm(x.Text) break end
                            end
                        end
                    end
                    if lbl and not seen[lbl] then
                        seen[lbl] = true
                        out.total = out.total + 1
                        if FEATURES[lbl] then
                            out.found = out.found + 1
                        else
                            out.missing[#out.missing + 1] = lbl
                        end
                    end
                end
            end
        end
    end
    return out
end
